// Package hub is the version/module router for gnomemepad.
//
// UI and tooling should resolve the active pad (and other modules) via hub
// instead of hardcoding padvN paths. Admins rotate module paths without
// redeploying every consumer.
//
//	Init â†’ SetModule("pad", "gno.land/r/.../padv4") â†’ GetModule("pad")
package hub

import (
	"chain"
	"strings"

	"gno.land/p/nt/avl/v0"
)

var (
	admin  address
	inited bool
	// modules: name -> package path string
	modules avl.Tree
)

// Init sets the hub admin (first EOA). Call once after deploy.
func Init(cur realm) {
	if inited {
		panic("hub: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("hub: EOA only")
	}
	admin = cur.Previous().Address()
	inited = true
	modules = avl.Tree{}
	chain.Emit("Init", "admin", admin.String())
}

func requireInit() {
	if !inited {
		panic("hub: call Init first")
	}
}

func requireAdmin(cur realm) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("hub: EOA only")
	}
	if cur.Previous().Address() != admin {
		panic("hub: not admin")
	}
}

// SetModule registers or updates a module path (admin only).
// name: short key e.g. "pad", "profile", "legacy_pad"
// path: full gno package path
func SetModule(cur realm, name, path string) {
	requireAdmin(cur)
	name = strings.TrimSpace(name)
	path = strings.TrimSpace(path)
	if name == "" || len(name) > 32 {
		panic("hub: invalid name")
	}
	if path == "" || len(path) > 200 {
		panic("hub: invalid path")
	}
	if !strings.HasPrefix(path, "gno.land/") {
		panic("hub: path must start with gno.land/")
	}
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-') {
			panic("hub: name charset")
		}
	}
	modules.Set(name, path)
	chain.Emit("SetModule", "name", name, "path", path)
}

// GetModule returns the package path for name, or "" if unset.
func GetModule(name string) string {
	requireInit()
	v := modules.Get(name)
	if v == nil {
		return ""
	}
	s, ok := v.(string)
	if !ok {
		return ""
	}
	return s
}

// ListModules returns newline-separated "name|path" lines (sorted by name).
func ListModules() string {
	requireInit()
	out := ""
	modules.Iterate("", "", func(key string, value any) bool {
		path, _ := value.(string)
		if out != "" {
			out += "\n"
		}
		out += key + "|" + path
		return false
	})
	return out
}

// TransferAdmin rotates hub admin.
func TransferAdmin(cur realm, newAdmin address) {
	requireAdmin(cur)
	if !newAdmin.IsValid() {
		panic("hub: invalid address")
	}
	if newAdmin == admin {
		panic("hub: same admin")
	}
	old := admin
	admin = newAdmin
	chain.Emit("TransferAdmin", "from", old.String(), "to", newAdmin.String())
}

// Admin returns the hub admin address.
func Admin() string {
	requireInit()
	return admin.String()
}

// Inited reports whether Init was called.
func Inited() bool {
	return inited
}

// Render â€” discovery home.
func Render(path string) string {
	path = strings.Trim(path, "/")
	if !inited {
		return "# gnomemepad hub\n\n> Not initialized. Call Init.\n"
	}
	out := "# gnomemepad hub\n\n"
	out += "- Admin: `" + admin.String() + "`\n\n"
	out += "## Modules\n\n"
	n := 0
	modules.Iterate("", "", func(key string, value any) bool {
		path, _ := value.(string)
		out += "- **" + key + "**: `" + path + "`\n"
		n++
		return false
	})
	if n == 0 {
		out += "_No modules registered. Admin: SetModule(name, path)._\n"
	}
	out += "\n## API\n\n"
	out += "- `GetModule(name)` / `ListModules()`\n"
	out += "- `SetModule(name, path)` â€” admin\n"
	out += "- `TransferAdmin(newAdmin)` â€” admin\n"
	_ = path
	return out
}

// resetForTest â€” unit tests only (unexported).
func resetForTest() {
	var zero address
	admin = zero
	inited = false
	modules = avl.Tree{}
}

// Package profile stores lightweight user profiles for gnomemepad.
// Independent of pad versions â€” upgrade this realm without redeploying markets.
//
//	SetProfile(displayName, bio, uri) â€” EOA only, per caller address
//	GetProfile(addr) â†’ name|bio|uri|updatedHeight
package profile

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	maxNameLen = 48
	maxBioLen  = 280
	maxURILen  = 200
)

// Profile is one user's public card (all fields exported for LaunchInfo-style reads).
type Profile struct {
	Name    string
	Bio     string
	URI     string
	Updated int64 // block height
}

var (
	// byAddr: address string -> *Profile
	byAddr avl.Tree
	inited bool
)

// Init is optional (no-op state). Kept for deploy symmetry with hub/pad.
func Init(cur realm) {
	if inited {
		panic("profile: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("profile: EOA only")
	}
	inited = true
	byAddr = avl.Tree{}
	chain.Emit("Init", "by", cur.Previous().Address().String())
}

func ensure() {
	// Lazy: allow SetProfile before Init for simpler UX; Init still recommended.
	if !inited {
		byAddr = avl.Tree{}
		inited = true
	}
}

func sanitizeText(s string, max int) string {
	s = strings.TrimSpace(s)
	if len(s) > max {
		s = s[:max]
	}
	// Strip control chars
	out := ""
	for _, c := range s {
		if c >= 0x20 && c != 0x7f {
			out += string(c)
		}
	}
	return out
}

// SetProfile upserts the caller's profile.
func SetProfile(cur realm, name, bio, uri string) {
	if !cur.Previous().IsUserCall() {
		panic("profile: EOA only")
	}
	ensure()
	name = sanitizeText(name, maxNameLen)
	bio = sanitizeText(bio, maxBioLen)
	uri = sanitizeText(uri, maxURILen)
	if name == "" {
		panic("profile: name required")
	}
	if uri != "" && !(strings.HasPrefix(uri, "https://") || strings.HasPrefix(uri, "http://") || strings.HasPrefix(uri, "ipfs://")) {
		panic("profile: uri must be http(s) or ipfs")
	}
	addr := cur.Previous().Address()
	p := &Profile{
		Name:    name,
		Bio:     bio,
		URI:     uri,
		Updated: runtime.ChainHeight(),
	}
	byAddr.Set(addr.String(), p)
	chain.Emit("SetProfile", "addr", addr.String(), "name", name)
}

// ClearProfile removes the caller's profile.
func ClearProfile(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("profile: EOA only")
	}
	ensure()
	addr := cur.Previous().Address().String()
	if byAddr.Has(addr) {
		byAddr.Remove(addr)
		chain.Emit("ClearProfile", "addr", addr)
	}
}

// GetProfile returns pipe-delimited: name|bio|uri|updatedHeight
// Empty string if none.
func GetProfile(addr string) string {
	ensure()
	addr = strings.TrimSpace(addr)
	if addr == "" {
		return ""
	}
	v := byAddr.Get(addr)
	if v == nil {
		return ""
	}
	p, ok := v.(*Profile)
	if !ok || p == nil {
		return ""
	}
	return p.Name + "|" + p.Bio + "|" + p.URI + "|" + strconv.FormatInt(p.Updated, 10)
}

// HasProfile reports whether addr has a profile.
func HasProfile(addr string) bool {
	ensure()
	return byAddr.Has(strings.TrimSpace(addr))
}

// ProfileCount returns number of profiles.
func ProfileCount() int {
	ensure()
	return byAddr.Size()
}

func sanitizeMD(s string) string {
	s = strings.ReplaceAll(s, "`", "'")
	s = strings.ReplaceAll(s, "<", "")
	s = strings.ReplaceAll(s, ">", "")
	return s
}

// Render home or user/{addr}
func Render(path string) string {
	path = strings.Trim(path, "/")
	ensure()
	if path == "" {
		out := "# gnomemepad profiles\n\n"
		out += "- Profiles: **" + strconv.Itoa(byAddr.Size()) + "**\n\n"
		out += "Call `SetProfile(name, bio, uri)` from your wallet.\n"
		return out
	}
	if strings.HasPrefix(path, "user/") {
		addr := strings.TrimPrefix(path, "user/")
		raw := GetProfile(addr)
		if raw == "" {
			return "> [!WARNING]\n> No profile for `" + sanitizeMD(addr) + "`\n"
		}
		parts := strings.SplitN(raw, "|", 4)
		name, bio, uri := parts[0], "", ""
		if len(parts) > 1 {
			bio = parts[1]
		}
		if len(parts) > 2 {
			uri = parts[2]
		}
		out := "# " + sanitizeMD(name) + "\n\n"
		out += "- Address: `" + sanitizeMD(addr) + "`\n"
		if bio != "" {
			out += "- Bio: " + sanitizeMD(bio) + "\n"
		}
		if uri != "" {
			out += "- URI: " + sanitizeMD(uri) + "\n"
		}
		return out
	}
	return "> [!WARNING]\n> Path not found\n"
}

func resetForTest() {
	byAddr = avl.Tree{}
	inited = false
}

// Package meta stores off-pad token presentation data (description, image, socials).
// Independent of pad versions â€” upgrade without redeploying markets.
//
// Key = padPkg + "|" + launchId
// First SetMeta caller becomes owner; only owner may update later.
package meta

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	maxDescLen    = 500
	maxURILen     = 200
	maxHandleLen  = 64
	maxPadPathLen = 200
	maxLaunchId   = 32
)

// TokenMeta is presentation data for one launch (not trading state).
type TokenMeta struct {
	PadPkg      string
	LaunchID    string
	Owner       address
	Description string
	ImageURI    string
	Website     string
	Twitter     string
	Telegram    string
	Updated     int64
}

var (
	// byKey: pad|id -> *TokenMeta
	byKey  avl.Tree
	inited bool
)

func Init(cur realm) {
	if inited {
		panic("meta: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("meta: EOA only")
	}
	inited = true
	byKey = avl.Tree{}
	chain.Emit("Init", "by", cur.Previous().Address().String())
}

func ensure() {
	if !inited {
		byKey = avl.Tree{}
		inited = true
	}
}

func makeKey(padPkg, launchID string) string {
	return padPkg + "|" + launchID
}

func sanitizeText(s string, max int) string {
	s = strings.TrimSpace(s)
	if len(s) > max {
		s = s[:max]
	}
	out := ""
	for _, c := range s {
		if c >= 0x20 && c != 0x7f {
			out += string(c)
		}
	}
	return out
}

func validateURI(uri string) {
	if uri == "" {
		return
	}
	if !(strings.HasPrefix(uri, "https://") || strings.HasPrefix(uri, "http://") || strings.HasPrefix(uri, "ipfs://")) {
		panic("meta: uri must be http(s) or ipfs")
	}
}

func validatePadPkg(padPkg string) {
	padPkg = strings.TrimSpace(padPkg)
	if padPkg == "" || len(padPkg) > maxPadPathLen {
		panic("meta: invalid pad path")
	}
	if !strings.HasPrefix(padPkg, "gno.land/r/") {
		panic("meta: pad must be gno.land/r/â€¦")
	}
}

// SetMeta upserts metadata for a launch. First writer owns the entry.
func SetMeta(cur realm, padPkg, launchID, description, imageURI, website, twitter, telegram string) {
	if !cur.Previous().IsUserCall() {
		panic("meta: EOA only")
	}
	ensure()
	validatePadPkg(padPkg)
	launchID = sanitizeText(launchID, maxLaunchId)
	if launchID == "" {
		panic("meta: launch id required")
	}
	description = sanitizeText(description, maxDescLen)
	imageURI = sanitizeText(imageURI, maxURILen)
	website = sanitizeText(website, maxURILen)
	twitter = sanitizeText(twitter, maxHandleLen)
	telegram = sanitizeText(telegram, maxHandleLen)
	validateURI(imageURI)
	validateURI(website)

	key := makeKey(padPkg, launchID)
	caller := cur.Previous().Address()
	existing := byKey.Get(key)
	if existing != nil {
		tm := existing.(*TokenMeta)
		if tm.Owner != caller {
			panic("meta: not owner")
		}
		tm.Description = description
		tm.ImageURI = imageURI
		tm.Website = website
		tm.Twitter = twitter
		tm.Telegram = telegram
		tm.Updated = runtime.ChainHeight()
		byKey.Set(key, tm)
	} else {
		tm := &TokenMeta{
			PadPkg:      padPkg,
			LaunchID:    launchID,
			Owner:       caller,
			Description: description,
			ImageURI:    imageURI,
			Website:     website,
			Twitter:     twitter,
			Telegram:    telegram,
			Updated:     runtime.ChainHeight(),
		}
		byKey.Set(key, tm)
	}
	chain.Emit("SetMeta", "key", key, "owner", caller.String())
}

// GetMeta returns:
//
//	owner|description|imageURI|website|twitter|telegram|updated
//
// Empty string if none.
func GetMeta(padPkg, launchID string) string {
	ensure()
	key := makeKey(strings.TrimSpace(padPkg), strings.TrimSpace(launchID))
	v := byKey.Get(key)
	if v == nil {
		return ""
	}
	tm := v.(*TokenMeta)
	return tm.Owner.String() + "|" +
		tm.Description + "|" +
		tm.ImageURI + "|" +
		tm.Website + "|" +
		tm.Twitter + "|" +
		tm.Telegram + "|" +
		strconv.FormatInt(tm.Updated, 10)
}

// HasMeta reports whether metadata exists.
func HasMeta(padPkg, launchID string) bool {
	ensure()
	return byKey.Has(makeKey(strings.TrimSpace(padPkg), strings.TrimSpace(launchID)))
}

// MetaCount returns number of entries.
func MetaCount() int {
	ensure()
	return byKey.Size()
}

// ClearMeta removes caller's owned entry.
func ClearMeta(cur realm, padPkg, launchID string) {
	if !cur.Previous().IsUserCall() {
		panic("meta: EOA only")
	}
	ensure()
	key := makeKey(strings.TrimSpace(padPkg), strings.TrimSpace(launchID))
	v := byKey.Get(key)
	if v == nil {
		return
	}
	tm := v.(*TokenMeta)
	if tm.Owner != cur.Previous().Address() {
		panic("meta: not owner")
	}
	byKey.Remove(key)
	chain.Emit("ClearMeta", "key", key)
}

func sanitizeMD(s string) string {
	s = strings.ReplaceAll(s, "`", "'")
	s = strings.ReplaceAll(s, "<", "")
	s = strings.ReplaceAll(s, ">", "")
	return s
}

func Render(path string) string {
	path = strings.Trim(path, "/")
	ensure()
	if path == "" {
		return "# gnomemepad meta\n\n- Entries: **" + strconv.Itoa(byKey.Size()) + "**\n\n" +
			"SetMeta(padPkg, launchID, description, imageURI, website, twitter, telegram)\n"
	}
	return "> [!WARNING]\n> Path not found: " + sanitizeMD(path) + "\n"
}

func resetForTest() {
	byKey = avl.Tree{}
	inited = false
}

// Package points is a lightweight referral + points ledger for gnomemepad.
// Independent of pad â€” does not verify trades on-chain (testnet growth layer).
//
//	SetReferrer(referrer) â€” once per user; both get bonus points
//	CheckIn() â€” daily points (1 per CheckInInterval heights)
//	GetPoints / GetReferrer / Leaderboard
//	AwardPoints â€” admin only (manual campaigns)
package points

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	// Points grants
	PointsReferrerBonus  int64 = 50  // to referrer when someone sets them
	PointsRefereeBonus   int64 = 25  // to new user on first referrer set
	PointsCheckIn        int64 = 5
	CheckInIntervalH     int64 = 100 // ~blocks between check-ins (testnet-friendly)
	LeaderboardMax       int   = 50
	MaxLeaderboardReturn int   = 20
)

var (
	admin  address
	inited bool
	// pointsByAddr: address string -> int64
	pointsByAddr avl.Tree
	// referrerOf: address string -> referrer address string
	referrerOf avl.Tree
	// lastCheckIn: address string -> height int64
	lastCheckIn avl.Tree
	// score index for leaderboard: zero-padded score + addr -> addr (desc via reverse iterate)
	// We keep simple: rebuild top from scan on Leaderboard() for MVP size.
)

func Init(cur realm) {
	if inited {
		panic("points: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("points: EOA only")
	}
	admin = cur.Previous().Address()
	inited = true
	pointsByAddr = avl.Tree{}
	referrerOf = avl.Tree{}
	lastCheckIn = avl.Tree{}
	chain.Emit("Init", "admin", admin.String())
}

func requireInit() {
	if !inited {
		panic("points: call Init first")
	}
}

func requireAdmin(cur realm) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("points: EOA only")
	}
	if cur.Previous().Address() != admin {
		panic("points: not admin")
	}
}

func getPts(addr string) int64 {
	v := pointsByAddr.Get(addr)
	if v == nil {
		return 0
	}
	n, ok := v.(int64)
	if !ok {
		return 0
	}
	return n
}

func addPts(addr string, delta int64) {
	if delta == 0 || addr == "" {
		return
	}
	cur := getPts(addr)
	next := cur + delta
	if next < 0 {
		next = 0
	}
	pointsByAddr.Set(addr, next)
}

// SetReferrer binds caller to a referrer once. Self-referral rejected.
func SetReferrer(cur realm, referrer address) {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("points: EOA only")
	}
	if !referrer.IsValid() {
		panic("points: invalid referrer")
	}
	me := cur.Previous().Address()
	if me == referrer {
		panic("points: cannot refer self")
	}
	meS := me.String()
	if referrerOf.Has(meS) {
		panic("points: referrer already set")
	}
	refS := referrer.String()
	referrerOf.Set(meS, refS)
	addPts(refS, PointsReferrerBonus)
	addPts(meS, PointsRefereeBonus)
	chain.Emit("SetReferrer", "user", meS, "referrer", refS)
}

// CheckIn grants PointsCheckIn if enough heights passed since last check-in.
func CheckIn(cur realm) int64 {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("points: EOA only")
	}
	me := cur.Previous().Address().String()
	h := runtime.ChainHeight()
	last := int64(0)
	if v := lastCheckIn.Get(me); v != nil {
		last, _ = v.(int64)
	}
	if last > 0 && h-last < CheckInIntervalH {
		panic("points: check-in too soon")
	}
	lastCheckIn.Set(me, h)
	addPts(me, PointsCheckIn)
	chain.Emit("CheckIn", "user", me, "points", strconv.FormatInt(PointsCheckIn, 10))
	return getPts(me)
}

// AwardPoints is admin-only (campaigns / corrections).
func AwardPoints(cur realm, to address, amount int64) {
	requireAdmin(cur)
	if !to.IsValid() {
		panic("points: invalid to")
	}
	if amount == 0 {
		panic("points: amount zero")
	}
	addPts(to.String(), amount)
	chain.Emit("Award", "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// GetPoints returns points for addr.
func GetPoints(addr string) int64 {
	requireInit()
	return getPts(strings.TrimSpace(addr))
}

// GetReferrer returns referrer address string or "".
func GetReferrer(addr string) string {
	requireInit()
	v := referrerOf.Get(strings.TrimSpace(addr))
	if v == nil {
		return ""
	}
	s, _ := v.(string)
	return s
}

// Leaderboard returns up to n lines "addr|points" sorted by points desc.
func Leaderboard(n int) string {
	requireInit()
	if n <= 0 {
		n = 10
	}
	if n > MaxLeaderboardReturn {
		n = MaxLeaderboardReturn
	}
	// Collect
	type row struct {
		addr string
		pts  int64
	}
	rows := make([]row, 0, LeaderboardMax)
	pointsByAddr.Iterate("", "", func(key string, value any) bool {
		pts, _ := value.(int64)
		if pts <= 0 {
			return false
		}
		rows = append(rows, row{addr: key, pts: pts})
		// soft cap collect
		if len(rows) >= LeaderboardMax {
			return true
		}
		return false
	})
	// Simple selection sort desc (small N)
	for i := 0; i < len(rows); i++ {
		best := i
		for j := i + 1; j < len(rows); j++ {
			if rows[j].pts > rows[best].pts {
				best = j
			}
		}
		rows[i], rows[best] = rows[best], rows[i]
	}
	if n > len(rows) {
		n = len(rows)
	}
	out := ""
	for i := 0; i < n; i++ {
		if out != "" {
			out += "\n"
		}
		out += rows[i].addr + "|" + strconv.FormatInt(rows[i].pts, 10)
	}
	return out
}

// UserCount returns addresses with any points.
func UserCount() int {
	requireInit()
	return pointsByAddr.Size()
}

// TransferAdmin rotates points admin.
func TransferAdmin(cur realm, newAdmin address) {
	requireAdmin(cur)
	if !newAdmin.IsValid() {
		panic("points: invalid address")
	}
	old := admin
	admin = newAdmin
	chain.Emit("TransferAdmin", "from", old.String(), "to", newAdmin.String())
}

// Admin returns admin address.
func Admin() string {
	requireInit()
	return admin.String()
}

// ParamsInfo for UI: referrerBonus|refereeBonus|checkIn|interval
func ParamsInfo() string {
	return strconv.FormatInt(PointsReferrerBonus, 10) + "|" +
		strconv.FormatInt(PointsRefereeBonus, 10) + "|" +
		strconv.FormatInt(PointsCheckIn, 10) + "|" +
		strconv.FormatInt(CheckInIntervalH, 10)
}

func Render(path string) string {
	path = strings.Trim(path, "/")
	if !inited {
		return "# gnomemepad points\n\n> Not initialized.\n"
	}
	out := "# gnomemepad points\n\n"
	out += "- Users with points: **" + strconv.Itoa(pointsByAddr.Size()) + "**\n"
	out += "- Check-in: **" + strconv.FormatInt(PointsCheckIn, 10) + "** pts / " + strconv.FormatInt(CheckInIntervalH, 10) + " heights\n\n"
	out += "## API\n\n- SetReferrer(addr)\n- CheckIn()\n- GetPoints(addr) / Leaderboard(n)\n"
	_ = path
	return out
}

func resetForTest() {
	var zero address
	admin = zero
	inited = false
	pointsByAddr = avl.Tree{}
	referrerOf = avl.Tree{}
	lastCheckIn = avl.Tree{}
}

// Package pad is gnomemepad: a self-contained meme launchpad for gno.land.
//
// Direction A â€” factory IS the market (no external AMM required for MVP):
//
//	Create â†’ GRC20 token + bonding curve â†’ Graduate (atomic locked CPMM)
//	â†’ GRC20 is listable on Gnoswap (external DEX); pad keeps locked pool too
//
// Tokens are real GRC20 (mint on buy, burn on sell) so holders can transfer and
// later provide liquidity on Gnoswap. Hybrid of Pump.fun + permanent LP lock.
package padv5

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/demo/tokens/grc20"
	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gnomemepad/ammmath"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/r/demo/defi/grc20reg"
)

var (
	launches     avl.Tree // id -> *Launch
	bySymbol     avl.Tree // symbol -> id string
	nextID       seqid.ID
	nextTokenID  seqid.ID // GRC20 identity sequence (shared for all launches)
	protocolAddr address
	protocolFees int64
	inited       bool
	// testSkipBanker: when true, sendUgnot is a no-op (unit tests without funded realm bank).
	// Always false in production.
	testSkipBanker bool
)

// Trade is one price sample for charts (capped history per launch).
type Trade struct {
	Height int64
	Side   int // TradeSideBuy | TradeSideSell | TradeSideOpen
	Ugnot  int64
	Tokens int64
	Price  int64 // ugnot per token * 1e6 after the trade
}

// Launch is one meme market: curve phase then locked pool phase.
// token/ledger are unexported so external packages cannot Mint/Burn via field access.
type Launch struct {
	ID      string
	Name    string
	Symbol  string
	URI     string
	Creator address
	Status  int
	Created int64 // block height

	// GRC20 (mint/burn only via pad-owned private ledger)
	token   *grc20.Token
	ledger  *grc20.PrivateLedger
	TokenID string // Token.ID() â€” registry / Gnoswap identity

	// Virtual curve reserves
	VirtualUgnot int64
	VirtualToken int64
	RealSold     int64 // tokens sold on curve (â‰¤ CurveSupply)
	RaisedUgnot  int64 // net ugnot collateral in curve (excl. fee vaults)

	// Real pool (post-grad); LP permanently locked â€” no remove path
	// PoolToken is pad-internal reserve (not the same as GRC20 total supply).
	PoolUgnot int64
	PoolToken int64

	CreatorFees  int64
	BondUgnot    int64
	BondRefunded bool
	UniqueBuyers avl.Tree // address -> true
	BuyerCount   int
	// snipeBought: address -> cumulative tokens bought during anti-snipe window
	snipeBought avl.Tree

	// Gnoswap listing readiness (GRC20 exists from Create; pool on Gnoswap is external)
	GnoswapReady bool // true after graduate â€” token may be paired on Gnoswap
	GnoswapNote  string

	// Chart history (ordered AVL keys)
	Trades    avl.Tree // tradeKey -> *Trade
	NextTrade int64
}

// Init sets the protocol treasury. First EOA caller becomes fee recipient.
func Init(cur realm) {
	if inited {
		panic("pad: already initialized")
	}
	if !cur.Previous().IsUserCall() {
		panic("pad: EOA only")
	}
	protocolAddr = cur.Previous().Address()
	inited = true
	chain.Emit("Init", "protocol", protocolAddr.String())
}

func requireInit() {
	if !inited {
		panic("pad: call Init first")
	}
}

func mustLaunch(id string) *Launch {
	// Sapphire avl.Tree.Get returns a single any (nil if missing).
	l, ok := launches.Get(id).(*Launch)
	if !ok {
		panic("pad: unknown launch")
	}
	return l
}

func balOf(l *Launch, addr address) int64 {
	if l == nil || l.token == nil {
		return 0
	}
	return l.token.BalanceOf(addr)
}

// addBal mints (delta>0) or burns (delta<0) GRC20 via pad-owned PrivateLedger.
func addBal(l *Launch, addr address, delta int64) {
	if l == nil || l.ledger == nil {
		panic("pad: missing GRC20 ledger")
	}
	if delta == 0 {
		return
	}
	if delta > 0 {
		if err := l.ledger.Mint(addr, delta); err != nil {
			panic("pad: mint: " + err.Error())
		}
		return
	}
	if err := l.ledger.Burn(addr, -delta); err != nil {
		panic("pad: burn: " + err.Error())
	}
}

func requireMinOut(got, minOut int64, what string) {
	if minOut < 0 {
		panic("pad: minOut must be non-negative")
	}
	if minOut > 0 && got < minOut {
		panic("pad: " + what + " below minOut (slippage)")
	}
}

func snipeBoughtOf(l *Launch, buyer address) int64 {
	v := l.snipeBought.Get(buyer.String())
	if v == nil {
		return 0
	}
	n, ok := v.(int64)
	if !ok {
		return 0
	}
	return n
}

func checkAndAddSnipe(l *Launch, buyer address, tokensOut int64) {
	height := runtime.ChainHeight()
	if height-l.Created >= AntiSnipeHeights {
		return
	}
	maxTok := TotalSupply * AntiSnipeMaxBuyBPS / 10000
	prev := snipeBoughtOf(l, buyer)
	if prev+tokensOut > maxTok {
		panic("pad: anti-snipe cumulative max buy exceeded")
	}
	l.snipeBought.Set(buyer.String(), prev+tokensOut)
}

func sendUgnot(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if testSkipBanker {
		return
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), to, chain.Coins{{Denom: DenomUgnot, Amount: amount}})
}

func requireUserPayment(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("pad: must be EOA MsgCall")
	}
	sent := unsafe.OriginSend().AmountOf(DenomUgnot)
	if sent <= 0 {
		panic("pad: need ugnot -send")
	}
	return sent
}

func noteBuyer(l *Launch, buyer address) {
	k := buyer.String()
	if l.UniqueBuyers.Has(k) {
		return
	}
	l.UniqueBuyers.Set(k, true)
	l.BuyerCount++
}

func tradeKey(n int64) string {
	s := strconv.FormatInt(n, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

// spotPriceScaled returns ugnot/token * 1e6 from current curve or pool reserves.
func spotPriceScaled(l *Launch) int64 {
	if l.Status == StatusGraduated {
		if l.PoolToken <= 0 {
			return 0
		}
		return l.PoolUgnot * 1000000 / l.PoolToken
	}
	if l.VirtualToken <= 0 {
		return 0
	}
	return l.VirtualUgnot * 1000000 / l.VirtualToken
}

func recordTrade(l *Launch, side int, ugnot, tokens int64) {
	l.NextTrade++
	t := &Trade{
		Height: runtime.ChainHeight(),
		Side:   side,
		Ugnot:  ugnot,
		Tokens: tokens,
		Price:  spotPriceScaled(l),
	}
	l.Trades.Set(tradeKey(l.NextTrade), t)
	// Ring buffer: drop oldest while over cap.
	for l.Trades.Size() > MaxTradeHistory {
		oldest := ""
		l.Trades.Iterate("", "", func(k string, _ any) bool {
			oldest = k
			return true // stop
		})
		if oldest == "" {
			break
		}
		l.Trades.Remove(oldest)
	}
}

func maybeRefundBond(cur realm, l *Launch) {
	if l.BondRefunded || l.BondUgnot <= 0 {
		return
	}
	if l.BuyerCount < BondRefundBuyers {
		return
	}
	// Quality gate: pure sybil micro-buys cannot refund bond.
	if l.RaisedUgnot < BondRefundMinRaised {
		return
	}
	if runtime.ChainHeight()-l.Created > BondRefundMaxHeights {
		return
	}
	amt := l.BondUgnot
	l.BondUgnot = 0
	l.BondRefunded = true
	sendUgnot(cur, l.Creator, amt)
	chain.Emit("BondRefund", "id", l.ID, "amount", strconv.FormatInt(amt, 10))
}

// Create deploys a fair-launch meme. Requires CreateBondUgnot via -send.
// No pre-mint; all tradeable float starts on the bonding curve.
func Create(cur realm, name, symbol, uri string) string {
	requireInit()
	sent := requireUserPayment(cur)
	if sent < CreateBondUgnot {
		panic("pad: create bond underpaid")
	}
	if name == "" || symbol == "" {
		panic("pad: name and symbol required")
	}
	if len(symbol) > 12 {
		panic("pad: symbol too long")
	}
	if bySymbol.Has(symbol) {
		panic("pad: symbol taken")
	}
	extra := sent - CreateBondUgnot
	if extra > 0 {
		protocolFees += extra
	}

	creator := cur.Previous().Address()
	id := nextID.Next().String()

	// Real GRC20 bound to this pad realm (mint/burn only via pad ledger).
	// Decimals=0: whole-token units (matches existing trade amounts).
	token, ledger := grc20.NewToken(name, symbol, 0, nextTokenID.Next(), cur)

	// Adena (and Gnoswap registries) resolve tokens ONLY via grc20reg under key
	// packagePath.SYMBOL â€” Token.ID() itself is packagePath.SYMBOL.seq and is
	// rejected as "Invalid path" if pasted into Adena without registration.
	// Skip in unit tests (testSkipBanker); production always registers.
	regKey := ""
	if !testSkipBanker {
		regKey = grc20reg.Register(cross(cur), token, symbol)
	}

	l := &Launch{
		ID:           id,
		Name:         name,
		Symbol:       symbol,
		URI:          uri,
		Creator:      creator,
		Status:       StatusCurve,
		Created:      runtime.ChainHeight(),
		token:        token,
		ledger:       ledger,
		TokenID:      token.ID(),
		VirtualUgnot: VirtualUgnot0,
		VirtualToken: VirtualToken0,
		UniqueBuyers: avl.Tree{},
		snipeBought:  avl.Tree{},
		BondUgnot:    CreateBondUgnot,
		Trades:       avl.Tree{},
	}
	// Open mark for charts (initial virtual spot).
	recordTrade(l, TradeSideOpen, 0, 0)
	launches.Set(id, l)
	bySymbol.Set(symbol, id)

	chain.Emit("Created",
		"id", id,
		"symbol", symbol,
		"creator", creator.String(),
		"token", l.TokenID,
		"reg", regKey,
	)
	return id
}

// AdenaPathOf returns the grc20reg / Adena token key: packagePath.SYMBOL
// (Token.ID is packagePath.SYMBOL.seq â€” Adena rejects that form).
func AdenaPathOf(id string) string {
	l := mustLaunch(id)
	return adenaKeyFromTokenID(l.TokenID, l.Symbol)
}

// adenaKeyFromTokenID strips the trailing .seq from Token.ID when present.
func adenaKeyFromTokenID(tokenID, symbol string) string {
	if tokenID == "" {
		return ""
	}
	// Token.ID = packagePath.symbol.seq â†’ registry key = packagePath.symbol
	suffix := "." + symbol + "."
	if i := strings.LastIndex(tokenID, suffix); i >= 0 {
		// packagePath + "." + symbol
		return tokenID[:i] + "." + symbol
	}
	// Already packagePath.symbol or unknown layout
	if strings.HasSuffix(tokenID, "."+symbol) {
		return tokenID
	}
	return tokenID
}

// Buy spends -send ugnot on the bonding curve; credits tokens to the caller.
// minTokensOut: slippage floor (0 = disabled). Auto-graduates at threshold.
// Oversized buys that would exceed remaining curve supply panic (no silent dust).
func Buy(cur realm, id string, minTokensOut int64) int64 {
	requireInit()
	sent := requireUserPayment(cur)
	l := mustLaunch(id)
	if l.Status != StatusCurve {
		panic("pad: not on curve (use SwapBuy)")
	}
	buyer := cur.Previous().Address()

	remaining := CurveSupply - l.RealSold
	if remaining <= 0 {
		panic("pad: curve sold out â€” call Graduate")
	}

	fee := ammmath.ApplyFee(sent, FeeBPS, CreatorFeeShareBPS, ProtocolFeeShareBPS)
	// Net enters curve; remainder boosts virtual ugnot (stays as collateral).
	netIn := fee.Net + fee.Remainder

	tokensOut, newVU, newVT := ammmath.BuyTokens(l.VirtualUgnot, l.VirtualToken, netIn)
	// Hard fail instead of partial fill + dust (audit Y2).
	if tokensOut > remaining {
		panic("pad: buy exceeds remaining curve supply â€” reduce amount")
	}
	requireMinOut(tokensOut, minTokensOut, "tokens out")
	checkAndAddSnipe(l, buyer, tokensOut)

	// Mutate only after all checks pass.
	l.CreatorFees += fee.Creator
	protocolFees += fee.Protocol
	l.VirtualUgnot = newVU
	l.VirtualToken = newVT
	l.RealSold += tokensOut
	l.RaisedUgnot += netIn

	addBal(l, buyer, tokensOut)
	noteBuyer(l, buyer)
	maybeRefundBond(cur, l)
	recordTrade(l, TradeSideBuy, sent, tokensOut)

	chain.Emit("Buy",
		"id", id,
		"buyer", buyer.String(),
		"ugnot", strconv.FormatInt(sent, 10),
		"tokens", strconv.FormatInt(tokensOut, 10),
	)

	if ammmath.CanGraduate(l.RaisedUgnot, GraduationThreshold) || l.RealSold >= CurveSupply {
		if l.RaisedUgnot >= GraduationThreshold {
			graduate(cur, l)
		}
	}
	return tokensOut
}

// Sell burns curve tokens and pays ugnot (fee on output).
// minUgnotOut: slippage floor (0 = disabled).
func Sell(cur realm, id string, tokensIn, minUgnotOut int64) int64 {
	requireInit()
	if !cur.Previous().IsUserCall() {
		panic("pad: must be EOA MsgCall")
	}
	if tokensIn <= 0 {
		panic("pad: tokensIn must be positive")
	}
	l := mustLaunch(id)
	if l.Status != StatusCurve {
		panic("pad: not on curve (use SwapSell)")
	}
	seller := cur.Previous().Address()
	if balOf(l, seller) < tokensIn {
		panic("pad: insufficient token balance")
	}

	gross, newVU, newVT := ammmath.SellTokens(l.VirtualUgnot, l.VirtualToken, tokensIn)
	fee := ammmath.ApplyFeeOnOutput(gross, FeeBPS, CreatorFeeShareBPS, ProtocolFeeShareBPS)
	requireMinOut(fee.Net, minUgnotOut, "ugnot out")

	// Full gross left virtual reserves; retain fee in virtual ugnot (cash stays in realm).
	l.VirtualUgnot = newVU + fee.Fee
	l.VirtualToken = newVT
	l.RealSold -= tokensIn
	if l.RealSold < 0 {
		l.RealSold = 0
	}

	// User receives net; creator+protocol become fee liabilities (leave Raised).
	payOut := fee.Net + fee.Creator + fee.Protocol
	if l.RaisedUgnot >= payOut {
		l.RaisedUgnot -= payOut
	} else {
		l.RaisedUgnot = 0
	}
	l.CreatorFees += fee.Creator
	protocolFees += fee.Protocol

	addBal(l, seller, -tokensIn)
	sendUgnot(cur, seller, fee.Net)
	recordTrade(l, TradeSideSell, fee.Net, tokensIn)

	chain.Emit("Sell",
		"id", id,
		"seller", seller.String(),
		"tokens", strconv.FormatInt(tokensIn, 10),
		"ugnot", strconv.FormatInt(fee.Net, 10),
	)
	return fee.Net
}

// Graduate permissionlessly moves a ready curve into a permanently locked CPMM.
func Graduate(cur realm, id string) {
	requireInit()
	l := mustLaunch(id)
	if l.Status != StatusCurve {
		panic("pad: already graduated")
	}
	if !ammmath.CanGraduate(l.RaisedUgnot, GraduationThreshold) {
		panic("pad: threshold not met")
	}
	graduate(cur, l)
}

func graduate(cur realm, l *Launch) {
	if l.Status != StatusCurve {
		return
	}
	// Seed pool: all curve collateral + remaining pool seed tokens.
	// Curve unsold tokens are not minted; only PoolSeed enters the pool.
	// Raised ugnot becomes pool ugnot (fee vaults stay separate liabilities).
	poolU := l.RaisedUgnot
	if poolU <= 0 {
		panic("pad: empty pool ugnot")
	}
	poolT := PoolSeed
	// Optional: if curve sold less than CurveSupply, unsold is never minted (dead supply).
	// Real circulating = RealSold + PoolSeed after minting pool to realm accounting.

	l.PoolUgnot = poolU
	l.PoolToken = poolT
	l.RaisedUgnot = 0
	l.VirtualUgnot = 0
	l.VirtualToken = 0
	l.Status = StatusGraduated

	// Pool tokens are held by the launch (not an address) â€” PoolToken reserve.
	// Circulating user balances remain; total effective supply = sum(balances)+PoolToken.

	// Forfeit unrefunded bond to protocol at graduation if still locked.
	if !l.BondRefunded && l.BondUgnot > 0 {
		protocolFees += l.BondUgnot
		l.BondUgnot = 0
		l.BondRefunded = true
	}

	// Mark graduation on chart at pool spot.
	recordTrade(l, TradeSideOpen, poolU, poolT)

	// GRC20 already exists and is transferable. Mark ready for external Gnoswap pool.
	// Pad keeps a locked internal CPMM; Gnoswap listing is a separate permissionless pool
	// seeded with GNOT + this GRC20 by the community/creator (see Guide).
	l.GnoswapReady = true
	l.GnoswapNote = "create GNOT/" + l.Symbol + " pool on Gnoswap with Token.ID=" + l.TokenID

	chain.Emit("Graduated",
		"id", l.ID,
		"poolUgnot", strconv.FormatInt(poolU, 10),
		"poolToken", strconv.FormatInt(poolT, 10),
		"token", l.TokenID,
		"gnoswap_ready", "1",
	)
	_ = cur // banker not needed; ugnot already on realm
}

