package encoding

import "encoding/binary"

// Uint64ToBigEndian - marshals uint64 to a bigendian byte slice so it can be
// sorted
func Uint64ToBigEndian(i uint64) []byte {
	b := make([]byte, 8)
	binary.BigEndian.PutUint64(b, i)
	return b
}

// BigEndianToUint64 returns an uint64 from big endian encoded bytes. If
// encoding is empty, zero is returned.
func BigEndianToUint64(bz []byte) uint64 {
	if len(bz) == 0 {
		return 0
	}

	return binary.BigEndian.Uint64(bz)
}

package proto

import (
	"encoding/binary"
	"time"

	"gno.land/p/nt/ufmt/v0"
)

type WireType int

const (
	VARINT  WireType = 0 //	int32, int64, uint32, uint64, sint32, sint64, bool, enum
	FIXED64 WireType = 1 // fixed64, sfixed64, double
	LEN     WireType = 2 // string, bytes, embedded messages, packed repeated fields
	FIXED32 WireType = 5 //	fixed32, sfixed32, float
)

// AppendVarint appends a varint field.
func AppendVarint(buf []byte, fieldNum int, v uint64) []byte {
	if v == 0 {
		return buf
	}
	buf = AppendTag(buf, fieldNum, VARINT)
	return binary.AppendUvarint(buf, v)
}

// MarshalAny returns the wire encoding of a google.protobuf.Any message
// holding (typeURL, value). Used to match the cdc.MarshalInterface format
// produced by the Cosmos SDK proto codec when storing or verifying
// interface-typed messages (e.g. ClientState in the upgrade store).
func MarshalAny(typeURL string, value []byte) []byte {
	var bz []byte
	bz = AppendLengthDelimited(bz, 1, []byte(typeURL))
	bz = AppendLengthDelimited(bz, 2, value)
	return bz
}

// AppendPackedVarintInt32 appends a packed repeated int32 varint field.
// Negative values are sign-extended to 64 bits to match proto3 wire format.
// Returns buf unchanged when values is empty (proto3 default).
func AppendPackedVarintInt32(buf []byte, fieldNum int, values []int32) []byte {
	if len(values) == 0 {
		return buf
	}
	var packed []byte
	for _, v := range values {
		packed = binary.AppendUvarint(packed, uint64(int64(v)))
	}
	buf = AppendTag(buf, fieldNum, LEN)
	buf = binary.AppendUvarint(buf, uint64(len(packed)))
	return append(buf, packed...)
}

// AppendFixed64 appends a fixed 64-bit field.
func AppendFixed64(buf []byte, fieldNum int, v uint64) []byte {
	if v == 0 {
		return buf
	}
	buf = AppendTag(buf, fieldNum, FIXED64)
	var b [8]byte
	binary.LittleEndian.PutUint64(b[:], v)
	return append(buf, b[:]...)
}

// AppendLengthDelimited appends a length-delimited field. Returns buf
// unchanged when bz is empty (proto3 default for optional fields).
func AppendLengthDelimited(buf []byte, fieldNum int, bz []byte) []byte {
	if len(bz) == 0 {
		return buf
	}
	buf = AppendTag(buf, fieldNum, LEN)
	buf = binary.AppendUvarint(buf, uint64(len(bz)))
	return append(buf, bz...)
}

// AppendAlwaysLengthDelimited appends a length-delimited field, including
// when bz is empty (emits a length-0 value). Required to match the wire
// format produced by gogoproto for fields marked
// `[(gogoproto.nullable) = false]`, which always serialize even when their
// underlying message has no non-zero fields.
func AppendAlwaysLengthDelimited(buf []byte, fieldNum int, bz []byte) []byte {
	buf = AppendTag(buf, fieldNum, LEN)
	buf = binary.AppendUvarint(buf, uint64(len(bz)))
	return append(buf, bz...)
}

// TimeMarshal returns a proto marshalled time.
func TimeMarshal(t time.Time) []byte {
	var (
		buf     []byte
		seconds = t.Unix()
		nanos   = int32(t.Nanosecond())
	)
	// Field 1: seconds (int64 - varint)
	buf = AppendVarint(buf, 1, uint64(seconds))
	// Field 2: nanos (int32 - varint)
	buf = AppendVarint(buf, 2, uint64(nanos))
	return buf
}

// AppendTime appends a google.protobuf.Timestamp field.
func AppendTime(buf []byte, fieldNum int, t time.Time) []byte {
	return AppendLengthDelimited(buf, fieldNum, TimeMarshal(t))
}

// DurationMarshal returns the inner proto encoding of a
// google.protobuf.Duration (without the length-delimited field wrapper).
func DurationMarshal(d time.Duration) []byte {
	var buf []byte
	seconds := d / time.Second
	nanos := int32(d % time.Second)
	if nanos < 0 {
		nanos += int32(time.Second)
	}
	buf = AppendVarint(buf, 1, uint64(seconds))
	buf = AppendVarint(buf, 2, uint64(nanos))
	return buf
}

// AppendDuration appends a google.protobuf.Duration field.
func AppendDuration(buf []byte, fieldNum int, d time.Duration) []byte {
	return AppendLengthDelimited(buf, fieldNum, DurationMarshal(d))
}

// AppendTag appends a protobuf tag (field number and wire type)
func AppendTag(buf []byte, fieldNum int, wireType WireType) []byte {
	tag := (fieldNum << 3) | int(wireType)
	return binary.AppendUvarint(buf, uint64(tag))
}

// DecodeVarint reads a varint from the byte slice and returns the value and new position
func DecodeVarint(buf []byte, pos int) (uint64, int, error) {
	if pos > len(buf) {
		return 0, pos, ufmt.Errorf("buffer underflow while reading varint")
	}
	v, n := binary.Uvarint(buf[pos:])
	if n == 0 {
		return 0, pos, ufmt.Errorf("buffer underflow while reading varint")
	}
	if n < 0 {
		return 0, pos + (-n), ufmt.Errorf("varint overflows uint64")
	}
	return v, pos + n, nil
}

// DecodeString reads a string (length-prefixed) from the byte slice
func DecodeString(buf []byte, pos int) (string, int, error) {
	length, newPos, err := DecodeVarint(buf, pos)
	if err != nil {
		return "", newPos, err
	}
	pos = newPos

	if length > uint64(len(buf)-pos) {
		return "", pos, ufmt.Errorf("buffer underflow while reading string")
	}

	end := pos + int(length)
	return string(buf[pos:end]), end, nil
}

package proto

import (
	"encoding/binary"
	"testing"
	"time"

	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

func TestAppendLengthDelimited(t *testing.T) {
	bz := AppendLengthDelimited(nil, 1, []byte("hello world"))

	uassert.Equal(t, "\n\vhello world", string(bz))
}

func TestAppendVarint(t *testing.T) {
	bz := AppendVarint(nil, 1, 42)

	uassert.Equal(t, "\b*", string(bz))
}

func TestAppendFixed64(t *testing.T) {
	bz := AppendFixed64(nil, 1, 42)

	uassert.Equal(t, "\t*\x00\x00\x00\x00\x00\x00\x00", string(bz))
}

func TestTimeMarshal(t *testing.T) {
	t.Run("zero time omits both fields", func(t *testing.T) {
		// time.Time{} has Unix == -62135596800 (year 1) but the proto3
		// encoding here treats it as a varint: nonzero seconds, zero nanos.
		bz := TimeMarshal(time.Unix(0, 0).UTC())
		// seconds=0 omitted, nanos=0 omitted
		uassert.Equal(t, 0, len(bz))
	})

	t.Run("seconds only", func(t *testing.T) {
		bz := TimeMarshal(time.Unix(1700000000, 0).UTC())
		// field 1 seconds: tag 0x08, varint 1700000000 = 0x80 0xe2 0xcf 0xaa 0x06
		uassert.Equal(t, "\x08\x80\xe2\xcf\xaa\x06", string(bz))
	})

	t.Run("seconds and nanos", func(t *testing.T) {
		bz := TimeMarshal(time.Unix(1, 500).UTC())
		// field 1: 08 01 ; field 2: 10 f4 03 (nanos = 500)
		uassert.Equal(t, "\x08\x01\x10\xf4\x03", string(bz))
	})
}

func TestAppendTime(t *testing.T) {
	bz := AppendTime(nil, 3, time.Unix(1700000000, 0).UTC())
	// field 3 LEN: tag 0x1a, length 6, then TimeMarshal output
	uassert.Equal(t, "\x1a\x06\x08\x80\xe2\xcf\xaa\x06", string(bz))
}

func TestDurationMarshal(t *testing.T) {
	t.Run("zero duration encodes to nothing", func(t *testing.T) {
		bz := DurationMarshal(0)
		uassert.Equal(t, 0, len(bz))
	})

	t.Run("seconds only", func(t *testing.T) {
		bz := DurationMarshal(3 * time.Second)
		// field 1 seconds=3: tag 0x08, varint 0x03
		uassert.Equal(t, "\x08\x03", string(bz))
	})

	t.Run("nanos only", func(t *testing.T) {
		bz := DurationMarshal(500 * time.Nanosecond)
		// field 2 nanos=500: tag 0x10, varint 500 = 0xf4 0x03
		uassert.Equal(t, "\x10\xf4\x03", string(bz))
	})

	t.Run("seconds and nanos", func(t *testing.T) {
		bz := DurationMarshal(time.Second + 500*time.Nanosecond)
		uassert.Equal(t, "\x08\x01\x10\xf4\x03", string(bz))
	})

	t.Run("negative nanos are normalized into the next-lower second", func(t *testing.T) {
		// proto3 Duration requires nanos in [0, 1e9). For a negative
		// total duration we add a full second to nanos to get a
		// non-negative remainder.
		bz := DurationMarshal(-500 * time.Nanosecond)
		// seconds = 0 (omitted), nanos = 1e9 - 500 = 999_999_500
		// 999_999_500 in varint: 0x8c 0x90 0xeb 0xdc 0x03
		uassert.Equal(t, "\x10\x8c\x90\xeb\xdc\x03", string(bz))
	})
}

func TestAppendDuration(t *testing.T) {
	bz := AppendDuration(nil, 4, 3*time.Second)
	// field 4 LEN: tag 0x22, length 2, then DurationMarshal output
	uassert.Equal(t, "\x22\x02\x08\x03", string(bz))
}

func TestMarshalAny(t *testing.T) {
	t.Run("typeURL only, empty value", func(t *testing.T) {
		bz := MarshalAny("/x.Y", nil)
		// Field 1 (typeURL): tag 0x0a, len 4, "/x.Y"
		uassert.Equal(t, "\n\x04/x.Y", string(bz))
	})

	t.Run("typeURL and value", func(t *testing.T) {
		bz := MarshalAny("/x.Y", []byte{0xab, 0xcd})
		// Field 1 (typeURL): tag 0x0a, len 4, "/x.Y"
		// Field 2 (value):   tag 0x12, len 2, 0xab 0xcd
		uassert.Equal(t, "\n\x04/x.Y\x12\x02\xab\xcd", string(bz))
	})
}

func TestAppendPackedVarintInt32(t *testing.T) {
	t.Run("empty omits field", func(t *testing.T) {
		bz := AppendPackedVarintInt32(nil, 1, nil)
		uassert.Equal(t, 0, len(bz))

		bz = AppendPackedVarintInt32(nil, 1, []int32{})
		uassert.Equal(t, 0, len(bz))
	})

	t.Run("includes zero values inside the packed payload", func(t *testing.T) {
		bz := AppendPackedVarintInt32(nil, 1, []int32{0, 1})
		// tag = 1<<3 | 2 = 0x0a, length = 2, payload = 0x00 0x01
		uassert.Equal(t, "\n\x02\x00\x01", string(bz))
	})

	t.Run("multi-byte varints", func(t *testing.T) {
		bz := AppendPackedVarintInt32(nil, 2, []int32{300, 1})
		// tag = 2<<3 | 2 = 0x12; 300 = 0xac 0x02 (varint); 1 = 0x01
		// length = 3
		uassert.Equal(t, "\x12\x03\xac\x02\x01", string(bz))
	})

	t.Run("appends to existing buffer", func(t *testing.T) {
		bz := AppendPackedVarintInt32([]byte{0xff}, 1, []int32{1})
		uassert.Equal(t, "\xff\n\x01\x01", string(bz))
	})
}

func TestDecodeVarint(t *testing.T) {
	maxUint64Varint := []byte{0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x01}
	overlongVarint := []byte{0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x02}

	testCases := []struct {
		name   string
		buf    []byte
		pos    int
		expVal uint64
		expPos int
		expErr string
	}{
		{"single byte zero", []byte{0x00}, 0, 0, 1, ""},
		{"single byte 1", []byte{0x01}, 0, 1, 1, ""},
		{"two-byte 150", []byte{0x96, 0x01}, 0, 150, 2, ""},
		{"non-zero start position", []byte{0xff, 0x96, 0x01, 0xff}, 1, 150, 3, ""},
		{"max uint64 (10-byte varint)", maxUint64Varint, 0, 1<<64 - 1, 10, ""},
		{"empty buffer", []byte{}, 0, 0, 0, "buffer underflow"},
		{"truncated continuation", []byte{0x80}, 0, 0, 0, "buffer underflow"},
		{"10-byte varint overflowing uint64 rejected", overlongVarint, 0, 0, 10, "varint overflows uint64"},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			v, p, err := DecodeVarint(tc.buf, tc.pos)
			if tc.expErr == "" {
				urequire.NoError(t, err)
				uassert.Equal(t, tc.expVal, v)
				uassert.Equal(t, tc.expPos, p)
				return
			}
			urequire.ErrorContains(t, err, tc.expErr)
			uassert.Equal(t, tc.expPos, p)
		})
	}
}

func TestDecodeString(t *testing.T) {
	t.Run("happy path", func(t *testing.T) {
		buf := append(binary.AppendUvarint(nil, 5), []byte("hello")...)
		got, p, err := DecodeString(buf, 0)
		urequire.NoError(t, err)
		uassert.Equal(t, "hello", got)
		uassert.Equal(t, len(buf), p)
	})

	t.Run("empty string", func(t *testing.T) {
		buf := binary.AppendUvarint(nil, 0)
		got, p, err := DecodeString(buf, 0)
		urequire.NoError(t, err)
		uassert.Equal(t, "", got)
		uassert.Equal(t, len(buf), p)
	})

	t.Run("truncated body", func(t *testing.T) {
		buf := append(binary.AppendUvarint(nil, 10), []byte("abc")...)
		_, _, err := DecodeString(buf, 0)
		urequire.ErrorContains(t, err, "buffer underflow")
	})

	t.Run("length 2^63 must not panic on int cast", func(t *testing.T) {
		buf := append(binary.AppendUvarint(nil, 1<<63), []byte("hi")...)
		_, _, err := DecodeString(buf, 0)
		urequire.ErrorContains(t, err, "buffer underflow")
	})

	t.Run("varint length parse error propagates", func(t *testing.T) {
		buf := []byte{0x80}
		_, _, err := DecodeString(buf, 0)
		urequire.ErrorContains(t, err, "varint")
	})

	t.Run("non-zero start position", func(t *testing.T) {
		// prefix byte + varint(5) + "hello" + trailing byte
		buf := []byte{0xff}
		buf = append(buf, binary.AppendUvarint(nil, 5)...)
		buf = append(buf, []byte("hello\xff")...)
		got, p, err := DecodeString(buf, 1)
		urequire.NoError(t, err)
		uassert.Equal(t, "hello", got)
		uassert.Equal(t, len(buf)-1, p)
	})
}

package merkle

import (
	"crypto/sha256"
)

// HashFromByteSlices computes a Merkle tree where the leaves are the byte
// slice, in the provided order. It follows RFC-6962.
func HashFromByteSlices(items [][]byte) []byte {
	switch len(items) {
	case 0:
		return emptyHash()
	case 1:
		return leafHash(items[0])
	default:
		// Find the split point (largest power of 2 <= len(items)).
		length := len(items)
		var k int
		for k = 1; k < length; k <<= 1 {
		}
		k >>= 1

		left := HashFromByteSlices(items[:k])
		right := HashFromByteSlices(items[k:])
		return innerHash(left, right)
	}
}

var (
	leafPrefix  = []byte{0x00}
	innerPrefix = []byte{0x01}
)

// emptyHash returns sha256(<empty>)
func emptyHash() []byte {
	bz := sha256.Sum256([]byte{})
	return bz[:]
}

// leafHash returns sha256(0x00 || leaf)
func leafHash(leaf []byte) []byte {
	bz := sha256.Sum256(append(leafPrefix, leaf...))
	return bz[:]
}

// innerHash returns sha256(0x01 || left || right)
func innerHash(left, right []byte) []byte {
	bz := sha256.Sum256(append(innerPrefix, append(left, right...)...))
	return bz[:]
}

