// 195 characters
var longID = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Duis eros neque, ultricies vel ligula ac, convallis porttitor elit. Maecenas tincidunt turpis elit, vel faucibus nisl pellentesque sodales"

type testCase struct {
	msg    string
	id     string
	expErr error
}

func TestDefaultIdentifierValidator(t *testing.T) {
	testCases := []testCase{
		{"valid lowercase", "lowercaseid", nil},
		{"valid id special chars", "._+-#[]<>._+-#[]<>", nil},
		{"valid id lower and special chars", "lower._+-#[]<>", nil},
		{"numeric id", "1234567890", nil},
		{"uppercase id", "NOTLOWERCASE", nil},
		{"numeric id", "1234567890", nil},
		{"blank id", "               ", errors.New("the ID is blank - contains only spaces")},
		{"id length out of range", "1", errors.New("the ID length is too short")},
		{"id is too long", "this identifier is too long to be used as a valid identifier", errors.New("the ID exceeds the maximum allowed length")},
		{"path-like id", "lower/case/id", errors.New("the ID contains path-like characters, which are invalid for an ID")},
		{"invalid id", "(clientid)", errors.New("the ID contains invalid characters")},
		{"empty string", "", errors.New("the ID cannot be empty")},
	}

	for _, tc := range testCases {
		err := host.ClientIdentifierValidator(tc.id)
		err2 := host.PortIdentifierValidator(tc.id)
		if tc.expErr == nil {
			urequire.NoError(t, err, tc.msg)
			urequire.NoError(t, err2, tc.msg)
		} else {
			urequire.Error(t, err, tc.msg)
			urequire.Error(t, err2, tc.msg)
		}
	}
}

func TestPortIdentifierValidator(t *testing.T) {
	testCases := []testCase{
		{"valid lowercase", "transfer", nil},
		{"valid id special chars", "._+-#[]<>._+-#[]<>", nil},
		{"valid id lower and special chars", "lower._+-#[]<>", nil},
		{"numeric id", "1234567890", nil},
		{"uppercase id", "NOTLOWERCASE", nil},
		{"numeric id", "1234567890", nil},
		{"blank id", "               ", errors.New("the ID is blank - contains only spaces")},
		{"id length out of range", "1", errors.New("the ID length is too short")},
		{"id is too long", longID, errors.New("the ID exceeds the maximum allowed length")},
		{"path-like id", "lower/case/id", errors.New("the ID contains path-like characters, which are invalid for an ID")},
		{"invalid id", "(clientid)", errors.New("the ID contains invalid characters")},
		{"empty string", "", errors.New("the ID cannot be empty")},
	}

	for _, tc := range testCases {
		err := host.PortIdentifierValidator(tc.id)
		if tc.expErr == nil {
			urequire.NoError(t, err, tc.msg)
		} else {
			urequire.Error(t, err, tc.msg)
		}
	}
}

package ics23

import (
	"bytes"
	"encoding/binary"
	"errors"

	// adds sha256 capability to crypto.SHA256

	"crypto/sha256"

	"gno.land/p/nt/ufmt/v0"
)

type HashOp int32

const (
	// NO_HASH is the default if no data passed. Note this is an illegal argument some places.
	HashOp_NO_HASH HashOp = 0
	HashOp_SHA256  HashOp = 1
)

// LengthOp defines how to process the key and value of the LeafOp
// to include length information. After encoding the length with the given
// algorithm, the length will be prepended to the key and value bytes.
// (Each one with it's own encoded length)
type LengthOp int32

const (
	// NO_PREFIX don't include any length info
	LengthOp_NO_PREFIX LengthOp = 0
	// VAR_PROTO uses protobuf (and go-amino) varint encoding of the length
	LengthOp_VAR_PROTO LengthOp = 1
)

// validateIavlOps validates the prefix to ensure it begins with
// the height, size, and version of the IAVL tree. Each varint must be a bounded value.
// In addition, the remaining bytes are validated to ensure they correspond to the correct
// length. The layerNum is the inverse of the tree depth, i.e. depth=0 means leaf, depth>=1 means inner node
func validateIavlOps(op opType, layerNum int) error {
	r := bytes.NewReader(op.GetPrefix())

	height, err := binary.ReadVarint(r)
	if err != nil {
		return ufmt.Errorf("failed to read IAVL height varint: %v", err)
	}
	if int(height) < 0 || int(height) < layerNum {
		return ufmt.Errorf("IAVL height (%d) must be non-negative and greater than or equal to the layer number (%d)", height, layerNum)
	}

	size, err := binary.ReadVarint(r)
	if err != nil {
		return ufmt.Errorf("failed to read IAVL size varint: %v", err)
	}

	if int(size) < 0 {
		return ufmt.Errorf("IAVL size must be non-negative")
	}

	version, err := binary.ReadVarint(r)
	if err != nil {
		return ufmt.Errorf("failed to read IAVL version varint: %v", err)
	}

	if int(version) < 0 {
		return ufmt.Errorf("IAVL version must be non-negative")
	}

	// grab the length of the remainder of the prefix
	remLen := r.Len()
	if layerNum == 0 {
		// leaf node
		if remLen != 0 {
			return ufmt.Errorf("expected remaining prefix length to be 0, got: %d", remLen)
		}
		if height != 0 {
			return ufmt.Errorf("expected leaf node height to be 0, got: %d", remLen)
		}
		if size != 1 {
			return ufmt.Errorf("expected leaf node size to be 1, got: %d", remLen)
		}
	} else {
		// inner node
		//
		// when the child comes from the left, the suffix if filled in
		// prefix: height | size | version | length byte (1 remainder)
		//
		// when the child comes from the right, the suffix is empty
		// prefix: height | size | version | length byte | 32 byte hash | next length byte (34 remainder)
		if remLen != 1 && remLen != 34 {
			return ufmt.Errorf("remainder of prefix must be of length 1 or 34, got: %d", remLen)
		}
		if op.GetHash() != HashOp_SHA256 {
			return ufmt.Errorf("IAVL hash op must be %v", HashOp_SHA256)
		}
	}
	return nil
}

// validateTendermintOps validates the prefix to ensure it begins with []byte{1}.
func validateTendermintOps(op *InnerOp) error {
	if len(op.Prefix) == 0 {
		return ufmt.Errorf("inner op prefix must not be empty")
	}

	innerPrefix := []byte{1}
	if op.Suffix != nil {
		if !bytes.Equal(op.Prefix, innerPrefix) {
			return ufmt.Errorf("expected inner op prefix: %v, got: %v", innerPrefix, op.Prefix)
		}
	}

	if !bytes.HasPrefix(op.Prefix, innerPrefix) {
		return ufmt.Errorf("expected inner op prefix to begin with: %v, got: %v", innerPrefix, op.Prefix[:1])
	}

	return nil
}

// Apply will calculate the leaf hash given the key and value being proven
func (op *LeafOp) Apply(key []byte, value []byte) ([]byte, error) {
	if len(key) == 0 {
		return nil, errors.New("leaf op needs key")
	}
	if len(value) == 0 {
		return nil, errors.New("leaf op needs value")
	}
	pkey, err := prepareLeafData(op.PrehashKey, op.Length, key)
	if err != nil {
		return nil, ufmt.Errorf("prehash key, %v", err)
	}
	pvalue, err := prepareLeafData(op.PrehashValue, op.Length, value)
	if err != nil {
		return nil, ufmt.Errorf("prehash value, %v", err)
	}

	data := op.Prefix
	data = append(data, pkey...)
	data = append(data, pvalue...)

	return doHash(op.Hash, data)
}

// Apply will calculate the hash of the next step, given the hash of the previous step
func (op *InnerOp) Apply(child []byte) ([]byte, error) {
	if len(child) == 0 {
		return nil, errors.New("inner op needs child value")
	}
	preimage := op.Prefix
	preimage = append(preimage, child...)
	preimage = append(preimage, op.Suffix...)
	return doHash(op.Hash, preimage)
}

// CheckAgainstSpec will verify the LeafOp is in the format defined in spec
func (op *LeafOp) CheckAgainstSpec(spec *ProofSpec) error {
	if spec == nil {
		return errors.New("op and spec must be non-nil")
	}
	lspec := spec.LeafSpec
	if lspec == nil {
		return errors.New("spec.LeafSpec must be non-nil")
	}

	if spec.SpecEquals(IavlSpec()) {
		err := validateIavlOps(op, 0)
		if err != nil {
			return err
		}
	}

	if op.Hash != lspec.Hash {
		return ufmt.Errorf("unexpected HashOp: %d", op.Hash)
	}
	if op.PrehashKey != lspec.PrehashKey {
		return ufmt.Errorf("unexpected PrehashKey: %d", op.PrehashKey)
	}
	if op.PrehashValue != lspec.PrehashValue {
		return ufmt.Errorf("unexpected PrehashValue: %d", op.PrehashValue)
	}
	if op.Length != lspec.Length {
		return ufmt.Errorf("unexpected LengthOp: %d", op.Length)
	}
	if !bytes.HasPrefix(op.Prefix, lspec.Prefix) {
		return ufmt.Errorf("leaf Prefix doesn't start with %X", lspec.Prefix)
	}
	return nil
}

// CheckAgainstSpec will verify the InnerOp is in the format defined in spec
func (op *InnerOp) CheckAgainstSpec(spec *ProofSpec, b int) error {
	if spec == nil {
		return errors.New("op and spec must be both non-nil")
	}
	if spec.InnerSpec == nil {
		return errors.New("spec.InnerSpec must be non-nil")
	}
	if spec.LeafSpec == nil {
		return errors.New("spec.LeafSpec must be non-nil")
	}

	if op.Hash != spec.InnerSpec.Hash {
		return ufmt.Errorf("unexpected HashOp: %d", op.Hash)
	}

	if spec.SpecEquals(IavlSpec()) {
		err := validateIavlOps(op, b)
		if err != nil {
			return err
		}
	}

	if spec.SpecEquals(TendermintSpec()) {
		err := validateTendermintOps(op)
		if err != nil {
			return err
		}
	}

	leafPrefix := spec.LeafSpec.Prefix
	if bytes.HasPrefix(op.Prefix, leafPrefix) {
		return ufmt.Errorf("inner Prefix starts with %X", leafPrefix)
	}
	if len(op.Prefix) < int(spec.InnerSpec.MinPrefixLength) {
		return ufmt.Errorf("innerOp prefix too short (%d)", len(op.Prefix))
	}
	maxLeftChildBytes := (len(spec.InnerSpec.ChildOrder) - 1) * int(spec.InnerSpec.ChildSize)
	if len(op.Prefix) > int(spec.InnerSpec.MaxPrefixLength)+maxLeftChildBytes {
		return ufmt.Errorf("innerOp prefix too long (%d)", len(op.Prefix))
	}

	if spec.InnerSpec.ChildSize <= 0 {
		return errors.New("spec.InnerSpec.ChildSize must be >= 1")
	}

	if spec.InnerSpec.MaxPrefixLength >= spec.InnerSpec.MinPrefixLength+spec.InnerSpec.ChildSize {
		return errors.New("spec.InnerSpec.MaxPrefixLength must be < spec.InnerSpec.MinPrefixLength + spec.InnerSpec.ChildSize")
	}

	// ensures soundness, with suffix having to be of correct length
	if len(op.Suffix)%int(spec.InnerSpec.ChildSize) != 0 {
		return ufmt.Errorf("InnerOp suffix malformed")
	}

	return nil
}

// doHash will preform the specified hash on the preimage.
// if hashOp == NONE, it will return an error (use doHashOrNoop if you want different behavior)
func doHash(hashOp HashOp, preimage []byte) ([]byte, error) {
	switch hashOp {
	case HashOp_SHA256:
		h := sha256.Sum256(preimage)
		return h[:], nil
	}
	return nil, ufmt.Errorf("unsupported hashop: %d", hashOp)
}

func prepareLeafData(hashOp HashOp, lengthOp LengthOp, data []byte) ([]byte, error) {
	// TODO: lengthop before or after hash ???
	hdata, err := doHashOrNoop(hashOp, data)
	if err != nil {
		return nil, err
	}

	return doLengthOp(lengthOp, hdata)
}

type opType interface {
	GetPrefix() []byte
	GetHash() HashOp
}

// doLengthOp will calculate the proper prefix and return it prepended
//
//	doLengthOp(op, data) -> length(data) || data
func doLengthOp(lengthOp LengthOp, data []byte) ([]byte, error) {
	switch lengthOp {
	case LengthOp_NO_PREFIX:
		return data, nil
	case LengthOp_VAR_PROTO:
		res := append(encodeVarintProto(len(data)), data...)
		return res, nil
	}
	return nil, ufmt.Errorf("unsupported lengthop: %d", lengthOp)
}

func encodeVarintProto(l int) []byte {
	// avoid multiple allocs for normal case
	res := make([]byte, 0, 8)
	for l >= 1<<7 {
		res = append(res, uint8(l&0x7f|0x80))
		l >>= 7
	}
	res = append(res, uint8(l))
	return res
}

// doHashOrNoop will return the preimage untouched if hashOp == NONE,
// otherwise, perform doHash
func doHashOrNoop(hashOp HashOp, preimage []byte) ([]byte, error) {
	if hashOp == HashOp_NO_HASH {
		return preimage, nil
	}
	return doHash(hashOp, preimage)
}

package ics23

import (
	"bytes"
	"errors"

	"gno.land/p/nt/ufmt/v0"
)

type CommitmentProof interface {
	GetExist() *ExistenceProof
	GetNonexist() *NonExistenceProof
}

type CommitmentProof_Exist struct {
	Exist *ExistenceProof
}

var _ CommitmentProof = CommitmentProof_Exist{}

func (c CommitmentProof_Exist) GetExist() *ExistenceProof       { return c.Exist }
func (c CommitmentProof_Exist) GetNonexist() *NonExistenceProof { return nil }

// ExistenceProof takes a key and a value and a set of steps to perform on it.
// The result of peforming all these steps will provide a "root hash", which can
// be compared to the value in a header.
//
// Since it is computationally infeasible to produce a hash collission for any of the used
// cryptographic hash functions, if someone can provide a series of operations to transform
// a given key and value into a root hash that matches some trusted root, these key and values
// must be in the referenced merkle tree.
//
// The only possible issue is maliablity in LeafOp, such as providing extra prefix data,
// which should be controlled by a spec. Eg. with lengthOp as NONE,
// prefix = FOO, key = BAR, value = CHOICE
// and
// prefix = F, key = OOBAR, value = CHOICE
// would produce the same value.
//
// With LengthOp this is tricker but not impossible. Which is why the "leafPrefixEqual" field
// in the ProofSpec is valuable to prevent this mutability. And why all trees should
// length-prefix the data before hashing it.
type ExistenceProof struct {
	Key   []byte
	Value []byte
	Leaf  *LeafOp
	Path  []*InnerOp
}

// LeafOp represents the raw key-value data we wish to prove, and
// must be flexible to represent the internal transformation from
// the original key-value pairs into the basis hash, for many existing
// merkle trees.
//
// key and value are passed in. So that the signature of this operation is:
// leafOp(key, value) -> output
//
// To process this, first prehash the keys and values if needed (ANY means no hash in this case):
// hkey = prehashKey(key)
// hvalue = prehashValue(value)
//
// Then combine the bytes, and hash it
// output = hash(prefix || length(hkey) || hkey || length(hvalue) || hvalue)
type LeafOp struct {
	Hash         HashOp
	PrehashKey   HashOp
	PrehashValue HashOp
	Length       LengthOp
	// prefix is a fixed bytes that may optionally be included at the beginning to differentiate
	// a leaf node from an inner node.
	Prefix []byte
}

func (m *LeafOp) GetHash() HashOp {
	if m != nil {
		return m.Hash
	}
	return HashOp_NO_HASH
}

func (m *LeafOp) GetPrefix() []byte {
	return m.Prefix
}

// InnerOp represents a merkle-proof step that is not a leaf.
// It represents concatenating two children and hashing them to provide the next result.
//
// The result of the previous step is passed in, so the signature of this op is:
// innerOp(child) -> output
//
// The result of applying InnerOp should be:
// output = op.hash(op.prefix || child || op.suffix)
//
// where the || operator is concatenation of binary data,
// and child is the result of hashing all the tree below this step.
//
// Any special data, like prepending child with the length, or prepending the entire operation with
// some value to differentiate from leaf nodes, should be included in prefix and suffix.
// If either of prefix or suffix is empty, we just treat it as an empty string
type InnerOp struct {
	Hash   HashOp
	Prefix []byte
	Suffix []byte
}

func (m *InnerOp) GetHash() HashOp {
	if m != nil {
		return m.Hash
	}
	return HashOp_NO_HASH
}

func (m *InnerOp) GetPrefix() []byte {
	return m.Prefix
}

// Verify does all checks to ensure this proof proves this key, value -> root
// and matches the spec.
func (p *ExistenceProof) Verify(spec *ProofSpec, root, key, value []byte) error {
	if err := p.CheckAgainstSpec(spec); err != nil {
		return err
	}

	if !bytes.Equal(key, p.Key) {
		return ufmt.Errorf("provided key doesn't match proof")
	}
	if !bytes.Equal(value, p.Value) {
		return ufmt.Errorf("provided value doesn't match proof")
	}

	calc, err := p.calculate(spec)
	if err != nil {
		return ufmt.Errorf("error calculating root, %v", err)
	}
	if !bytes.Equal(root, calc) {
		return ufmt.Errorf("calculated root doesn't match provided root")
	}

	return nil
}

// Calculate determines the root hash that matches the given proof.
// You must validate the result is what you have in a header.
// Returns error if the calculations cannot be performed.
func (p *ExistenceProof) Calculate() ([]byte, error) {
	return p.calculate(nil)
}

func (p *ExistenceProof) calculate(spec *ProofSpec) ([]byte, error) {
	if p.Leaf == nil {
		return nil, errors.New("existence Proof needs defined LeafOp")
	}

	// leaf step takes the key and value as input
	res, err := p.Leaf.Apply(p.Key, p.Value)
	if err != nil {
		return nil, ufmt.Errorf("leaf, %v", err)
	}

	// the rest just take the output of the last step (reducing it)
	for _, step := range p.Path {
		res, err = step.Apply(res)
		if err != nil {
			return nil, ufmt.Errorf("inner, %v", err)
		}
		if spec != nil {
			if len(res) > int(spec.InnerSpec.ChildSize) && int(spec.InnerSpec.ChildSize) >= 32 {
				return nil, ufmt.Errorf("inner, %v", err)
			}
		}
	}
	return res, nil
}

type CommitmentProof_Nonexist struct {
	Nonexist *NonExistenceProof
}

var _ CommitmentProof = CommitmentProof_Nonexist{}

func (c CommitmentProof_Nonexist) GetExist() *ExistenceProof       { return nil }
func (c CommitmentProof_Nonexist) GetNonexist() *NonExistenceProof { return c.Nonexist }

// NonExistenceProof takes a proof of two neighbors, one left of the desired key,
// one right of the desired key. If both proofs are valid AND they are neighbors,
// then there is no valid proof for the given key.
type NonExistenceProof struct {
	Key   []byte
	Left  *ExistenceProof
	Right *ExistenceProof
}

// Calculate determines the root hash that matches the given nonexistence proof.
// You must validate the result is what you have in a header.
// Returns error if the calculations cannot be performed.
func (p *NonExistenceProof) Calculate() ([]byte, error) {
	// A Nonexist proof may have left or right proof nil
	switch {
	case p.Left != nil:
		return p.Left.Calculate()
	case p.Right != nil:
		return p.Right.Calculate()
	default:
		return nil, errors.New("nonexistence proof has empty Left and Right proof")
	}
}

// CheckAgainstSpec will verify the leaf and all path steps are in the format defined in spec
func (p *ExistenceProof) CheckAgainstSpec(spec *ProofSpec) error {
	leaf := p.Leaf
	if leaf == nil {
		return errors.New("existence Proof needs defined LeafOp")
	}
	if err := leaf.CheckAgainstSpec(spec); err != nil {
		return ufmt.Errorf("leaf, %v", err)
	}
	if spec.MinDepth > 0 && len(p.Path) < int(spec.MinDepth) {
		return ufmt.Errorf("innerOps depth too short: %d", len(p.Path))
	}

	maxDepth := spec.MaxDepth
	if maxDepth == 0 {
		maxDepth = 128
	}

	if len(p.Path) > int(maxDepth) {
		return ufmt.Errorf("innerOps depth too long: %d", len(p.Path))
	}

	layerNum := 1

	for _, inner := range p.Path {
		if err := inner.CheckAgainstSpec(spec, layerNum); err != nil {
			return ufmt.Errorf("inner, %v", err)
		}
		layerNum++
	}
	return nil
}

// If we should prehash the key before comparison, do so; otherwise, return the key. Prehashing
// changes lexical comparison, so we do so before comparison if the spec sets
// `PrehashKeyBeforeComparison`.
func keyForComparison(spec *ProofSpec, key []byte) []byte {
	if !spec.PrehashKeyBeforeComparison {
		return key
	}
	hash, _ := doHashOrNoop(spec.LeafSpec.PrehashKey, key)
	return hash
}

// Verify does all checks to ensure the proof has valid non-existence proofs,
// and they ensure the given key is not in the CommitmentState
func (p *NonExistenceProof) Verify(spec *ProofSpec, root, key []byte) error {
	// ensure the existence proofs are valid
	var leftKey, rightKey []byte
	if p.Left != nil {
		if err := p.Left.Verify(spec, root, p.Left.Key, p.Left.Value); err != nil {
			return ufmt.Errorf("left proof, %v", err)
		}
		leftKey = p.Left.Key
	}
	if p.Right != nil {
		if err := p.Right.Verify(spec, root, p.Right.Key, p.Right.Value); err != nil {
			return ufmt.Errorf("right proof, %v", err)
		}
		rightKey = p.Right.Key
	}

	// If both proofs are missing, this is not a valid proof
	if leftKey == nil && rightKey == nil {
		return errors.New("both left and right proofs missing")
	}

	// Ensure in valid range
	if rightKey != nil {
		if bytes.Compare(keyForComparison(spec, key), keyForComparison(spec, rightKey)) >= 0 {
			return errors.New("key is not left of right proof")
		}
	}

	if leftKey != nil {
		if bytes.Compare(keyForComparison(spec, key), keyForComparison(spec, leftKey)) <= 0 {
			return errors.New("key is not right of left proof")
		}
	}

	switch {
	case leftKey == nil:
		isLeftMost, err := IsLeftMost(spec.InnerSpec, p.Right.Path)
		if err != nil {
			return err
		}

		if !isLeftMost {
			return errors.New("left proof missing, right proof must be left-most")
		}
	case rightKey == nil:
		isRightMost, err := IsRightMost(spec.InnerSpec, p.Left.Path)
		if err != nil {
			return err
		}

		if !isRightMost {
			return errors.New("right proof missing, left proof must be right-most")
		}
	default:
		isLeftNeighbor, err := IsLeftNeighbor(spec.InnerSpec, p.Left.Path, p.Right.Path)
		if err != nil {
			return err
		}

		if !isLeftNeighbor {
			return errors.New("right proof missing, left proof must be right-most")
		}
	}

	return nil
}

// IsLeftMost returns true if this is the left-most path in the tree, excluding placeholder (empty child) nodes
func IsLeftMost(spec *InnerSpec, path []*InnerOp) (bool, error) {
	minPrefix, maxPrefix, suffix, err := getPadding(spec, 0)
	if err != nil {
		return false, err
	}

	// ensure every step has a prefix and suffix defined to be leftmost, unless it is a placeholder node
	for _, step := range path {
		if !hasPadding(step, minPrefix, maxPrefix, suffix) {
			leftBranchesAreEmpty, err := leftBranchesAreEmpty(spec, step)
			if err != nil {
				return false, err
			}

			if !leftBranchesAreEmpty {
				return false, nil
			}
		}
	}
	return true, nil
}

// IsRightMost returns true if this is the right-most path in the tree, excluding placeholder (empty child) nodes
func IsRightMost(spec *InnerSpec, path []*InnerOp) (bool, error) {
	last := len(spec.ChildOrder) - 1
	minPrefix, maxPrefix, suffix, err := getPadding(spec, int32(last))
	if err != nil {
		return false, err
	}

	// ensure every step has a prefix and suffix defined to be rightmost, unless it is a placeholder node
	for _, step := range path {
		if !hasPadding(step, minPrefix, maxPrefix, suffix) {
			rightBranchesAreEmpty, err := rightBranchesAreEmpty(spec, step)
			if err != nil {
				return false, err
			}

			if !rightBranchesAreEmpty {
				return false, nil
			}
		}
	}
	return true, nil
}

// IsLeftNeighbor returns true if `right` is the next possible path right of `left`
//
//	Find the common suffix from the Left.Path and Right.Path and remove it. We have LPath and RPath now, which must be neighbors.
//	Validate that LPath[len-1] is the left neighbor of RPath[len-1]
//	For step in LPath[0..len-1], validate step is right-most node
//	For step in RPath[0..len-1], validate step is left-most node
func IsLeftNeighbor(spec *InnerSpec, left []*InnerOp, right []*InnerOp) (bool, error) {
	if len(left) == 0 || len(right) == 0 {
		return false, nil
	}

	// count common tail (from end, near root)
	left, topleft := left[:len(left)-1], left[len(left)-1]
	right, topright := right[:len(right)-1], right[len(right)-1]
	for bytes.Equal(topleft.Prefix, topright.Prefix) && bytes.Equal(topleft.Suffix, topright.Suffix) {
		if len(left) == 0 || len(right) == 0 {
			return false, nil
		}
		left, topleft = left[:len(left)-1], left[len(left)-1]
		right, topright = right[:len(right)-1], right[len(right)-1]
	}

	// now topleft and topright are the first divergent nodes
	// make sure they are left and right of each other
	ok, err := isLeftStep(spec, topleft, topright)
	if err != nil {
		return false, err
	}
	if !ok {
		return false, nil
	}

	// left and right are remaining children below the split,
	// ensure left child is the rightmost path, and visa versa
	isRightMost, err := IsRightMost(spec, left)
	if err != nil {
		return false, err
	}
	if !isRightMost {
		return false, nil
	}

	isLeftMost, err := IsLeftMost(spec, right)
	if err != nil {
		return false, err
	}
	if !isLeftMost {
		return false, nil
	}
	return true, nil
}

// isLeftStep assumes left and right have common parents
// checks if left is exactly one slot to the left of right
func isLeftStep(spec *InnerSpec, left *InnerOp, right *InnerOp) (bool, error) {
	leftidx, err := orderFromPadding(spec, left)
	if err != nil {
		return false, err
	}
	rightidx, err := orderFromPadding(spec, right)
	if err != nil {
		return false, err
	}

	// TODO: is it possible there are empty (nil) children???
	return rightidx == leftidx+1, nil
}

// checks if an op has the expected padding
func hasPadding(op *InnerOp, minPrefix, maxPrefix, suffix int) bool {
	if len(op.Prefix) < minPrefix {
		return false
	}
	if len(op.Prefix) > maxPrefix {
		return false
	}
	return len(op.Suffix) == suffix
}

// getPadding determines prefix and suffix with the given spec and position in the tree
func getPadding(spec *InnerSpec, branch int32) (minPrefix, maxPrefix, suffix int, err error) {
	idx, err := getPosition(spec.ChildOrder, branch)
	if err != nil {
		return 0, 0, 0, err
	}

	// count how many children are in the prefix
	prefix := idx * int(spec.ChildSize)
	minPrefix = prefix + int(spec.MinPrefixLength)
	maxPrefix = prefix + int(spec.MaxPrefixLength)

	// count how many children are in the suffix
	suffix = (len(spec.ChildOrder) - 1 - idx) * int(spec.ChildSize)
	return minPrefix, maxPrefix, suffix, nil
}

// leftBranchesAreEmpty returns true if the padding bytes correspond to all empty siblings
// on the left side of a branch, ie. it's a valid placeholder on a leftmost path
func leftBranchesAreEmpty(spec *InnerSpec, op *InnerOp) (bool, error) {
	idx, err := orderFromPadding(spec, op)
	if err != nil {
		return false, err
	}
	// count branches to left of this
	leftBranches := int(idx)
	if leftBranches == 0 {
		return false, nil
	}
	// compare prefix with the expected number of empty branches
	actualPrefix := len(op.Prefix) - leftBranches*int(spec.ChildSize)
	if actualPrefix < 0 {
		return false, nil
	}
	for i := 0; i < leftBranches; i++ {
		idx, err := getPosition(spec.ChildOrder, int32(i))
		if err != nil {
			return false, err
		}

		from := actualPrefix + idx*int(spec.ChildSize)
		if !bytes.Equal(spec.EmptyChild, op.Prefix[from:from+int(spec.ChildSize)]) {
			return false, nil
		}
	}
	return true, nil
}

// rightBranchesAreEmpty returns true if the padding bytes correspond to all empty siblings
// on the right side of a branch, ie. it's a valid placeholder on a rightmost path
func rightBranchesAreEmpty(spec *InnerSpec, op *InnerOp) (bool, error) {
	idx, err := orderFromPadding(spec, op)
	if err != nil {
		return false, err
	}
	// count branches to right of this one
	rightBranches := len(spec.ChildOrder) - 1 - int(idx)
	if rightBranches == 0 {
		return false, nil
	}
	// compare suffix with the expected number of empty branches
	if len(op.Suffix) != rightBranches*int(spec.ChildSize) {
		return false, nil // sanity check
	}
	for i := 0; i < rightBranches; i++ {
		idx, err := getPosition(spec.ChildOrder, int32(i))
		if err != nil {
			return false, err
		}

		from := idx * int(spec.ChildSize)
		if !bytes.Equal(spec.EmptyChild, op.Suffix[from:from+int(spec.ChildSize)]) {
			return false, nil
		}
	}
	return true, nil
}

// getPosition checks where the branch is in the order and returns
// the index of this branch
func getPosition(order []int32, branch int32) (int, error) {
	if branch < 0 || int(branch) >= len(order) {
		return -1, ufmt.Errorf("invalid branch: %d", branch)
	}
	for i, item := range order {
		if branch == item {
			return i, nil
		}
	}

	return -1, ufmt.Errorf("branch %d not found in order %v", branch, order)
}

// This will look at the proof and determine which order it is...
// So we can see if it is branch 0, 1, 2 etc... to determine neighbors
func orderFromPadding(spec *InnerSpec, inner *InnerOp) (int32, error) {
	maxbranch := int32(len(spec.ChildOrder))
	for branch := int32(0); branch < maxbranch; branch++ {
		minp, maxp, suffix, err := getPadding(spec, branch)
		if err != nil {
			return 0, err
		}
		if hasPadding(inner, minp, maxp, suffix) {
			return branch, nil
		}
	}
	return 0, errors.New("cannot find any valid spacing for this node")
}

// Equal returns true if the two ProofSpec instances are deeply equal across
// every field. Use this when you need a strict content comparison (e.g. to
// detect attempts at substituting a different spec for an existing client).
// For the looser, "same shape" comparison historically used to route proof
// verification through IavlSpec/TendermintSpec, use SpecEquals instead.
func (p *ProofSpec) Equal(other *ProofSpec) bool {
	if p == nil || other == nil {
		return p == other
	}
	if p.MaxDepth != other.MaxDepth ||
		p.MinDepth != other.MinDepth ||
		p.PrehashKeyBeforeComparison != other.PrehashKeyBeforeComparison {
		return false
	}
	if !p.LeafSpec.Equal(other.LeafSpec) {
		return false
	}
	return p.InnerSpec.Equal(other.InnerSpec)
}

// Equal returns true if the two LeafOp instances are deeply equal.
func (p *LeafOp) Equal(other *LeafOp) bool {
	if p == nil || other == nil {
		return p == other
	}
	return p.Hash == other.Hash &&
		p.PrehashKey == other.PrehashKey &&
		p.PrehashValue == other.PrehashValue &&
		p.Length == other.Length &&
		bytes.Equal(p.Prefix, other.Prefix)
}

// Equal returns true if the two InnerSpec instances are deeply equal.
func (p *InnerSpec) Equal(other *InnerSpec) bool {
	if p == nil || other == nil {
		return p == other
	}
	if p.ChildSize != other.ChildSize ||
		p.MinPrefixLength != other.MinPrefixLength ||
		p.MaxPrefixLength != other.MaxPrefixLength ||
		p.Hash != other.Hash {
		return false
	}
	if len(p.ChildOrder) != len(other.ChildOrder) {
		return false
	}
	for i := range p.ChildOrder {
		if p.ChildOrder[i] != other.ChildOrder[i] {
			return false
		}
	}
	return bytes.Equal(p.EmptyChild, other.EmptyChild)
}

// SpecEquals returns true if two ProofSpec instances match on the subset of
// fields that matter for routing proof verification through a known spec
// (IavlSpec/TendermintSpec). It intentionally ignores MaxDepth/MinDepth,
// LeafOp.Prefix, ChildOrder contents, and InnerSpec.EmptyChild — it
// over-declares equality, which we consider fine for that use case.
// Use Equal for strict field-by-field comparison (e.g. RecoverClient).
func (p *ProofSpec) SpecEquals(spec *ProofSpec) bool {
	// 1. Compare LeafSpecs values.
	switch {
	case (p.LeafSpec == nil) != (spec.LeafSpec == nil): // One of them is nil.
		return false

	case p.LeafSpec != nil && spec.LeafSpec != nil:
		ok := p.LeafSpec.Hash == spec.LeafSpec.Hash &&
			p.LeafSpec.PrehashKey == spec.LeafSpec.PrehashKey &&
			p.LeafSpec.PrehashValue == spec.LeafSpec.PrehashValue &&
			p.LeafSpec.Length == spec.LeafSpec.Length
		if !ok {
			return false
		}

	default: // Both are nil, hence LeafSpec values are equal.
	}

	// 2. Compare InnerSpec values.
	switch {
	case (p.InnerSpec == nil) != (spec.InnerSpec == nil): // One of them is not nil.
		return false

	case p.InnerSpec != nil && spec.InnerSpec != nil: // Both are non-nil
		ok := p.InnerSpec.Hash == spec.InnerSpec.Hash &&
			p.InnerSpec.MinPrefixLength == spec.InnerSpec.MinPrefixLength &&
			p.InnerSpec.MaxPrefixLength == spec.InnerSpec.MaxPrefixLength &&
			p.InnerSpec.ChildSize == spec.InnerSpec.ChildSize &&
			len(p.InnerSpec.ChildOrder) == len(spec.InnerSpec.ChildOrder)
		if !ok {
			return false
		}

	default: // Both are nil, hence InnerSpec values are equal.
	}

	// By this point all the above conditions pass so they are equal.
	return true
}

package ics23_test

import (
	"encoding/hex"
	"testing"

	"gno.land/p/aib/ics23"
	"gno.land/p/nt/uassert/v0"
)

func TestProofSpecEqual(t *testing.T) {
	newLeaf := func() *ics23.LeafOp {
		return &ics23.LeafOp{
			Prefix:       []byte{0},
			PrehashKey:   ics23.HashOp_NO_HASH,
			Hash:         ics23.HashOp_SHA256,
			PrehashValue: ics23.HashOp_SHA256,
			Length:       ics23.LengthOp_VAR_PROTO,
		}
	}
	newInner := func() *ics23.InnerSpec {
		return &ics23.InnerSpec{
			ChildOrder:      []int32{0, 1},
			MinPrefixLength: 4,
			MaxPrefixLength: 12,
			ChildSize:       33,
			EmptyChild:      nil,
			Hash:            ics23.HashOp_SHA256,
		}
	}
	newSpec := func() *ics23.ProofSpec {
		return &ics23.ProofSpec{
			LeafSpec:                   newLeaf(),
			InnerSpec:                  newInner(),
			MaxDepth:                   0,
			MinDepth:                   0,
			PrehashKeyBeforeComparison: false,
		}
	}

	testCases := []struct {
		name     string
		malleate func(a, b *ics23.ProofSpec)
		expEqual bool
	}{
		{"equal — same fresh spec", func(a, b *ics23.ProofSpec) {}, true},
		{"equal — same as well-known IavlSpec", func(a, b *ics23.ProofSpec) {
			*a = *ics23.IavlSpec()
			*b = *ics23.IavlSpec()
		}, true},
		{"differ — MaxDepth", func(a, b *ics23.ProofSpec) { b.MaxDepth = 10 }, false},
		{"differ — MinDepth", func(a, b *ics23.ProofSpec) { b.MinDepth = 1 }, false},
		{"differ — PrehashKeyBeforeComparison", func(a, b *ics23.ProofSpec) { b.PrehashKeyBeforeComparison = true }, false},
		{"differ — LeafSpec.Hash", func(a, b *ics23.ProofSpec) { b.LeafSpec.Hash = ics23.HashOp_NO_HASH }, false},
		{"differ — LeafSpec.PrehashKey", func(a, b *ics23.ProofSpec) { b.LeafSpec.PrehashKey = ics23.HashOp_SHA256 }, false},
		{"differ — LeafSpec.PrehashValue", func(a, b *ics23.ProofSpec) { b.LeafSpec.PrehashValue = ics23.HashOp_NO_HASH }, false},
		{"differ — LeafSpec.Length", func(a, b *ics23.ProofSpec) { b.LeafSpec.Length = ics23.LengthOp_NO_PREFIX }, false},
		{"differ — LeafSpec.Prefix", func(a, b *ics23.ProofSpec) { b.LeafSpec.Prefix = []byte{1} }, false},
		{"differ — LeafSpec nil vs non-nil", func(a, b *ics23.ProofSpec) { b.LeafSpec = nil }, false},
		{"differ — InnerSpec.ChildSize", func(a, b *ics23.ProofSpec) { b.InnerSpec.ChildSize = 32 }, false},
		{"differ — InnerSpec.MinPrefixLength", func(a, b *ics23.ProofSpec) { b.InnerSpec.MinPrefixLength = 1 }, false},
		{"differ — InnerSpec.MaxPrefixLength", func(a, b *ics23.ProofSpec) { b.InnerSpec.MaxPrefixLength = 99 }, false},
		{"differ — InnerSpec.Hash", func(a, b *ics23.ProofSpec) { b.InnerSpec.Hash = ics23.HashOp_NO_HASH }, false},
		{"differ — InnerSpec.ChildOrder length", func(a, b *ics23.ProofSpec) { b.InnerSpec.ChildOrder = []int32{0, 1, 2} }, false},
		{"differ — InnerSpec.ChildOrder content", func(a, b *ics23.ProofSpec) { b.InnerSpec.ChildOrder = []int32{1, 0} }, false},
		{"differ — InnerSpec.EmptyChild", func(a, b *ics23.ProofSpec) { b.InnerSpec.EmptyChild = []byte{0, 0, 0} }, false},
		{"differ — InnerSpec nil vs non-nil", func(a, b *ics23.ProofSpec) { b.InnerSpec = nil }, false},
	}
	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			a, b := newSpec(), newSpec()
			tc.malleate(a, b)
			uassert.Equal(t, tc.expEqual, a.Equal(b), "a.Equal(b)")
			// Equal must be symmetric.
			uassert.Equal(t, tc.expEqual, b.Equal(a), "b.Equal(a)")
		})
	}
}

func TestProofSpecEqualNil(t *testing.T) {
	spec := ics23.IavlSpec()

	var nilSpec *ics23.ProofSpec
	uassert.True(t, nilSpec.Equal(nil), "nil.Equal(nil) must be true")
	uassert.False(t, spec.Equal(nil), "non-nil.Equal(nil) must be false")
	uassert.False(t, nilSpec.Equal(spec), "nil.Equal(non-nil) must be false")
}

func TestLeafOpEqual(t *testing.T) {
	var nilOp *ics23.LeafOp
	uassert.True(t, nilOp.Equal(nil))

	a := &ics23.LeafOp{Hash: ics23.HashOp_SHA256, Prefix: []byte{0x01}}
	b := &ics23.LeafOp{Hash: ics23.HashOp_SHA256, Prefix: []byte{0x01}}
	uassert.True(t, a.Equal(b))
	uassert.False(t, a.Equal(nil))

	b.Prefix = []byte{0x02}
	uassert.False(t, a.Equal(b))
}

func TestInnerSpecEqual(t *testing.T) {
	var nilSpec *ics23.InnerSpec
	uassert.True(t, nilSpec.Equal(nil))

	a := &ics23.InnerSpec{ChildOrder: []int32{0, 1}, ChildSize: 33, Hash: ics23.HashOp_SHA256}
	b := &ics23.InnerSpec{ChildOrder: []int32{0, 1}, ChildSize: 33, Hash: ics23.HashOp_SHA256}
	uassert.True(t, a.Equal(b))
	uassert.False(t, a.Equal(nil))

	b.ChildSize = 32
	uassert.False(t, a.Equal(b))
}

func TestLeafOpProtoMarshal(t *testing.T) {
	t.Run("nil receiver returns nil", func(t *testing.T) {
		var nilLeaf *ics23.LeafOp
		uassert.Equal(t, 0, len(nilLeaf.ProtoMarshal()))
	})

	t.Run("matches expected wire format for IavlSpec.LeafSpec", func(t *testing.T) {
		bz := ics23.IavlSpec().LeafSpec.ProtoMarshal()
		// Field 1 (Hash=SHA256=1):     08 01
		// Field 2 (PrehashKey=0):      omitted
		// Field 3 (PrehashValue=1):    18 01
		// Field 4 (Length=VAR_PROTO=1):20 01
		// Field 5 (Prefix=[0x00]):     2a 01 00
		uassert.Equal(t, "0801180120012a0100", hex.EncodeToString(bz))
	})
}

func TestInnerSpecProtoMarshal(t *testing.T) {
	t.Run("nil receiver returns nil", func(t *testing.T) {
		var nilInner *ics23.InnerSpec
		uassert.Equal(t, 0, len(nilInner.ProtoMarshal()))
	})

	t.Run("matches expected wire format for IavlSpec.InnerSpec", func(t *testing.T) {
		bz := ics23.IavlSpec().InnerSpec.ProtoMarshal()
		// Field 1 (ChildOrder=[0,1] packed): 0a 02 00 01
		// Field 2 (ChildSize=33):            10 21
		// Field 3 (MinPrefixLength=4):       18 04
		// Field 4 (MaxPrefixLength=12):      20 0c
		// Field 5 (EmptyChild=nil):          omitted
		// Field 6 (Hash=SHA256=1):           30 01
		uassert.Equal(t, "0a02000110211804200c3001", hex.EncodeToString(bz))
	})
}

func TestProofSpecProtoMarshal(t *testing.T) {
	t.Run("nil receiver returns nil", func(t *testing.T) {
		var nilSpec *ics23.ProofSpec
		uassert.Equal(t, 0, len(nilSpec.ProtoMarshal()))
	})

	t.Run("matches expected wire format for IavlSpec", func(t *testing.T) {
		bz := ics23.IavlSpec().ProtoMarshal()
		// Field 1 (LeafSpec, len=9):  0a 09 <leaf bytes>
		// Field 2 (InnerSpec, len=12):12 0c <inner bytes>
		// Fields 3,4,5: omitted (zero defaults)
		want := "0a090801180120012a0100" + "120c0a02000110211804200c3001"
		uassert.Equal(t, want, hex.EncodeToString(bz))
	})

	t.Run("optional fields are emitted when set", func(t *testing.T) {
		spec := &ics23.ProofSpec{
			MaxDepth:                   8,
			MinDepth:                   1,
			PrehashKeyBeforeComparison: true,
		}
		bz := spec.ProtoMarshal()
		// Field 3 (MaxDepth=8):                         18 08
		// Field 4 (MinDepth=1):                         20 01
		// Field 5 (PrehashKeyBeforeComparison=true):    28 01
		uassert.Equal(t, "180820012801", hex.EncodeToString(bz))
	})
}

func TestIsLeftNeighbor_NoPanicOnEdgeCases(cur realm, t *testing.T) {
	spec := ics23.IavlSpec().InnerSpec
	childSize := int(spec.ChildSize)

	validOp := func() *ics23.InnerOp {
		return &ics23.InnerOp{Prefix: []byte("aaaa"), Suffix: make([]byte, childSize)}
	}
	convergingOp := func() *ics23.InnerOp {
		return &ics23.InnerOp{Prefix: []byte("aaaa"), Suffix: make([]byte, childSize)}
	}
	malformedOp := func() *ics23.InnerOp {
		return &ics23.InnerOp{Prefix: make([]byte, 100), Suffix: nil}
	}

	cases := []struct {
		name      string
		left      []*ics23.InnerOp
		right     []*ics23.InnerOp
		expectErr bool
	}{
		{"empty left path", nil, []*ics23.InnerOp{validOp()}, false},
		{"empty right path", []*ics23.InnerOp{validOp()}, nil, false},
		{"common suffix exhausted", []*ics23.InnerOp{convergingOp()}, []*ics23.InnerOp{convergingOp()}, false},
		{"malformed left prefix", []*ics23.InnerOp{malformedOp()}, []*ics23.InnerOp{validOp()}, true},
		{"malformed right prefix", []*ics23.InnerOp{validOp()}, []*ics23.InnerOp{malformedOp()}, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var (
				ok  bool
				err error
			)
			uassert.NotPanics(t, cur, func() {
				ok, err = ics23.IsLeftNeighbor(spec, tc.left, tc.right)
			})
			uassert.False(t, ok, "expected isNeighbor=false")
			if tc.expectErr {
				uassert.Error(t, err, "expected error for malformed input")
			} else {
				uassert.NoError(t, err)
			}
		})
	}
}

package ics23

import (
	"gno.land/p/aib/encoding/proto"
)

// GetSDKSpecs returns the proof specs of an SDK chain.
func GetSDKProofSpecs() []*ProofSpec {
	return []*ProofSpec{IavlSpec(), TendermintSpec()}
}

// IavlSpec constrains the format from proofs-iavl (iavl merkle proofs)
func IavlSpec() *ProofSpec {
	return &ProofSpec{
		LeafSpec: &LeafOp{
			Prefix:       []byte{0},
			PrehashKey:   HashOp_NO_HASH,
			Hash:         HashOp_SHA256,
			PrehashValue: HashOp_SHA256,
			Length:       LengthOp_VAR_PROTO,
		},
		InnerSpec: &InnerSpec{
			ChildOrder:      []int32{0, 1},
			MinPrefixLength: 4,
			MaxPrefixLength: 12,
			ChildSize:       33, // (with length byte)
			EmptyChild:      nil,
			Hash:            HashOp_SHA256,
		},
	}
}

// TendermintSpec constrains the format from proofs-tendermint (crypto/merkle SimpleProof)
func TendermintSpec() *ProofSpec {
	return &ProofSpec{
		LeafSpec: &LeafOp{
			Prefix:       []byte{0},
			PrehashKey:   HashOp_NO_HASH,
			Hash:         HashOp_SHA256,
			PrehashValue: HashOp_SHA256,
			Length:       LengthOp_VAR_PROTO,
		},
		InnerSpec: &InnerSpec{
			ChildOrder:      []int32{0, 1},
			MinPrefixLength: 1,
			MaxPrefixLength: 1,
			ChildSize:       32, // (no length byte)
			Hash:            HashOp_SHA256,
		},
	}
}

// ProofSpec defines what the expected parameters are for a given proof type.
// This can be stored in the client and used to validate any incoming proofs.
//
// verify(ProofSpec, Proof) -> Proof | Error
//
// As demonstrated in tests, if we don't fix the algorithm used to calculate the
// LeafHash for a given tree, there are many possible key-value pairs that can
// generate a given hash (by interpretting the preimage differently).
// We need this for proper security, requires client knows a priori what
// tree format server uses. But not in code, rather a configuration object.
type ProofSpec struct {
	// any field in the ExistenceProof must be the same as in this spec.
	// except Prefix, which is just the first bytes of prefix (spec can be longer)
	LeafSpec  *LeafOp
	InnerSpec *InnerSpec
	// max_depth (if > 0) is the maximum number of InnerOps allowed (mainly for fixed-depth tries)
	// the max_depth is interpreted as 128 if set to 0
	MaxDepth int32
	// min_depth (if > 0) is the minimum number of InnerOps allowed (mainly for fixed-depth tries)
	MinDepth int32
	// prehash_key_before_comparison is a flag that indicates whether to use the
	// prehash_key specified by LeafOp to compare lexical ordering of keys for
	// non-existence proofs.
	PrehashKeyBeforeComparison bool
}

// InnerSpec contains all store-specific structure info to determine if two proofs from a
// given store are neighbors.
//
// This enables:
//
// isLeftMost(spec: InnerSpec, op: InnerOp)
// isRightMost(spec: InnerSpec, op: InnerOp)
// isLeftNeighbor(spec: InnerSpec, left: InnerOp, right: InnerOp)
type InnerSpec struct {
	// Child order is the ordering of the children node, must count from 0
	// iavl tree is [0, 1] (left then right)
	// merk is [0, 2, 1] (left, right, here)
	ChildOrder      []int32
	ChildSize       int32
	MinPrefixLength int32
	MaxPrefixLength int32
	// empty child is the prehash image that is used when one child is nil (eg. 20 bytes of 0)
	EmptyChild []byte
	// hash is the algorithm that must be used for each InnerOp
	Hash HashOp
}

// ProtoMarshal returns the proto3 wire encoding of the ProofSpec, matching
// the format produced by gogoproto in cosmos/ics23. A nil receiver is encoded
// as an empty byte slice (proto3 unset message).
func (p *ProofSpec) ProtoMarshal() []byte {
	if p == nil {
		return nil
	}
	var bz []byte
	bz = proto.AppendLengthDelimited(bz, 1, p.LeafSpec.ProtoMarshal())
	bz = proto.AppendLengthDelimited(bz, 2, p.InnerSpec.ProtoMarshal())
	bz = proto.AppendVarint(bz, 3, uint64(int64(p.MaxDepth)))
	bz = proto.AppendVarint(bz, 4, uint64(int64(p.MinDepth)))
	if p.PrehashKeyBeforeComparison {
		bz = proto.AppendVarint(bz, 5, 1)
	}
	return bz
}

// ProtoMarshal returns the proto3 wire encoding of the LeafOp.
func (p *LeafOp) ProtoMarshal() []byte {
	if p == nil {
		return nil
	}
	var bz []byte
	bz = proto.AppendVarint(bz, 1, uint64(int64(p.Hash)))
	bz = proto.AppendVarint(bz, 2, uint64(int64(p.PrehashKey)))
	bz = proto.AppendVarint(bz, 3, uint64(int64(p.PrehashValue)))
	bz = proto.AppendVarint(bz, 4, uint64(int64(p.Length)))
	bz = proto.AppendLengthDelimited(bz, 5, p.Prefix)
	return bz
}

// ProtoMarshal returns the proto3 wire encoding of the InnerSpec. ChildOrder
// is encoded as a packed repeated int32 field per proto3 default.
func (p *InnerSpec) ProtoMarshal() []byte {
	if p == nil {
		return nil
	}
	var bz []byte
	bz = proto.AppendPackedVarintInt32(bz, 1, p.ChildOrder)
	bz = proto.AppendVarint(bz, 2, uint64(int64(p.ChildSize)))
	bz = proto.AppendVarint(bz, 3, uint64(int64(p.MinPrefixLength)))
	bz = proto.AppendVarint(bz, 4, uint64(int64(p.MaxPrefixLength)))
	bz = proto.AppendLengthDelimited(bz, 5, p.EmptyChild)
	bz = proto.AppendVarint(bz, 6, uint64(int64(p.Hash)))
	return bz
}

